window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["U4"]={"deck":"U4","slides":[{"p":1,"title":"04 독일공작연맹과 바우하우스, 데 스테일 (표지)","terms":["Deutscher Werkbund","Bauhaus","De Stijl"],"pass1":[{"kind":"say","lines":["4단원 표지예요. 노란 띠에 제목 한 줄만 있어요.","제목은 '04 독일공작연맹과 바우하우스/데 스테일' 이에요.","이 과목의 주문을 다시 외워요. 기계 시대에 건축은 어떻게 생겨야 하나?","1단원부터의 순서는 싫어 → 새 장식 → 정리 → 없애 였어요."]}],"pass2":[{"kind":"points","head":"4단원에서 만날 차례","items":["1) **합리주의**와 **모더니즘**이 왜 생겼는지 (p.2-3)","2) 선구 작품 세 개: 페레, 베렌스, 그로피우스 (p.4-6)","3) **독일공작연맹(Deutscher Werkbund)** 과 1914년 쾰른 전시회 (p.7-8)","4) **바우하우스(Bauhaus)** 학교와 데사우 교사 (p.9-24)","5) 국제주의, 기능주의, 그리고 **데 스테일(De Stijl)** (p.25-41)"]},{"kind":"points","head":"이 표지에서 기억할 한 가지","items":["4단원은 '없애' 다음 칸이에요. 장식을 없앤 다음 무엇을 하느냐를 다뤄요.","답은 '기계로 좋은 것을 많이 만들자' 예요.","**데 스테일(De Stijl)** 은 그 흐름을 직선과 3원색으로 밀어붙인 네덜란드 편이에요."]}],"pass3":[]},{"p":2,"title":"모더니즘의 출현: 기계론적 세계관과 합리주의","terms":["기계론적 세계관","합리주의","모더니즘","Expressionism"],"pass1":[{"kind":"analogy","head":"시계 속 톱니바퀴","scene":"시계를 열면 톱니가 정확히 맞물려 규칙대로 돌아가요.","map":[["톱니가 규칙대로 도는 시계","**기계론적 세계관**"],["따져 보면 다 맞아떨어진다는 믿음","**합리주의**"],["화려한 장식이 붙은 옛 시계","배제된 바로크와 로코코"]]},{"kind":"say","lines":["한 줄로 하면 이래요. 기계가 세상을 바꾸니 생각도 기계처럼 바뀌었어요.","머리로 따지면 다 풀린다는 태도, 이것이 **합리주의**예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**기계론적 세계관**: 세상이 기계 부품처럼 정해진 규칙대로 움직인다고 보는 생각이에요.","**합리주의**: 현실의 모든 문제를 이성으로 풀 수 있다고 믿는 태도예요.","**모더니즘**: 새 기술과 새 생활방식에 맞춰 나타난 새 형태 전체의 이름이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["계기가 된 사건은 1765년 **증기기관**의 발명이에요. 연도를 꼭 외워요.","이때 바로크와 로코코 양식이 배제되고 **합리주의**가 태동해요.","**합리주의**는 **표현주의(Expressionism)** 와 반대 입장이에요. 6단원에서 다시 만나요.","목표가 둘이에요. 좋은 사회를 위한 윤리적 행위, 그리고 경제성 충족이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"공간디자인사에서 **합리주의**가 태동한 계기로 강의가 든 사건은 무엇일까요?","choices":["1851년 런던 만국박람회","1765년 증기기관의 발명","1789년 프랑스 혁명"],"a":1,"why":"1765년 증기기관의 발명 같은 기계문명의 발전이 계기예요."},{"kind":"check","q":"**합리주의**와 반대 입장으로 소개된 경향은 무엇일까요?","choices":["**표현주의(Expressionism)**","**기계론적 세계관**","**모더니즘**"],"a":0,"why":"합리주의는 이성, 표현주의는 주관과 감정이에요. 정반대 편이에요."},{"kind":"english","head":"논술 답안: 합리주의의 태동","en":"1765년 증기기관의 발명과 같은 기계문명의 발전을 계기로 바로크 및 로코코 양식이 배제되고, 절제되고 엄격한 법칙과 명확한 공간질서를 추구하는 합리주의가 태동하였다.","ko":"계기(1765 증기기관), 버린 것(바로크, 로코코), 추구한 것(법칙과 질서) 세 덩어리예요.","tip":"'증기기관 → 바로크 아웃 → 질서 인' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.05,0.26,0.06],"c":[0.047,0.025,0.286,0.11],"r":3.4667,"img":"img/U4/walk/p002_22_01.jpg","say":"제목은 '모더니즘의 출현' 이에요. 이 쪽의 주제예요."},{"b":[0.05,0.15,0.92,0.16],"c":[0,0.1278,1,0.2045],"r":6.52,"img":"img/U4/walk/p002_22_02.jpg","say":"첫 소제목 '기계론적 세계관과 합리주의' 와 그 설명 두 줄이에요. 공간 설계에도 영향을 미쳤대요."},{"b":[0.05,0.315,0.92,0.07],"c":[0,0.2478,1,0.2045],"r":6.52,"img":"img/U4/walk/p002_22_03.jpg","say":"'기술의존적 합리주의 경향과 같은 맥락' 이라는 줄이에요."},{"b":[0.08,0.385,0.88,0.155],"c":[0.032,0.3647,0.968,0.1956],"r":6.5985,"img":"img/U4/walk/p002_22_04.jpg","say":"1765년 증기기관 → 바로크, 로코코 배제 → 합리주의 태동."},{"b":[0.08,0.55,0.88,0.1],"c":[0.032,0.5022,0.968,0.1956],"r":6.5985,"img":"img/U4/walk/p002_22_05.jpg","say":"합리주의의 정의예요. 이성에 대한 신뢰가 바탕이에요."},{"b":[0.08,0.66,0.88,0.19],"c":[0.032,0.644,0.968,0.222],"r":5.8138,"img":"img/U4/walk/p002_22_06.jpg","say":"'표현주의와 반대 입장', 윤리적 행위, 경제성 충족 세 줄이에요."}]}},{"p":3,"title":"모더니즘과 국제주의 양식, 역사주의 기반 VS 기술문명 지향","terms":["모더니즘","합리주의","Bauhaus","International Style","신즉물주의","Expressionism"],"pass1":[{"kind":"say","lines":["이 쪽은 4단원부터 6단원까지의 지도예요.","20세기 초 예술 전체에 나타난 새 형태의 이름이 **모더니즘**이에요.","아래쪽은 편 가르기예요. 옛것 편과 기술 편으로 나뉘어요."]},{"kind":"compare","head":"두 편 한눈에","cols":["역사주의 기반","기술문명 지향"],"rows":[["과거의 구축양식을 모방","자연의 모방을 부정하는 기술지향"],["유겐트슈틸, 자연주의적 경향","기하학적 경향, **신즉물주의**"],["표현주의적 경향, 암스테르담파","독일 **모더니즘**, 국제주의 건축"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**모더니즘**: 회화, 조각, 건축, 음악, 문학에 나타난 새 형태에 주어진 이름이에요.","**국제주의 양식(International Style)**: 기술개발의 성과를 구축 형태의 원형으로 받아들인 양식이에요.","**신즉물주의**: 기술문명 지향 편에 속하는 반 표현주의적 전위예술이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**바우하우스(Bauhaus)** 로 대표되는 독일 **합리주의**는 산업화 시대 건축과 디자인의 규범이에요.","1920년대에 **합리주의**가 **국제주의 양식(International Style)** 으로 발전해요.","**표현주의(Expressionism)** 와 암스테르담파는 역사주의 기반 편이에요. 6단원 내용이에요.","**신즉물주의**는 기술문명 지향 편이에요. 편이 헷갈리기 쉬워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"강의의 분류에서 '기술문명 지향' 쪽에 속하는 것은 무엇일까요?","choices":["유겐트슈틸","암스테르담파","**신즉물주의**"],"a":2,"why":"신즉물주의는 반 표현주의적 전위예술이라 기술문명 지향 편이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["유겐트슈틸과 암스테르담파는 기술 편이 아니라 역사주의 기반 편이에요.","**국제주의 양식(International Style)** 은 1920년대에 **합리주의**가 자란 결과예요. 출발점이 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.08,0.92,0.1],"c":[0,0.0278,1,0.2045],"r":6.52,"img":"img/U4/walk/p003_22_01.jpg","say":"20세기 초 디자인의 가장 중요한 발전을 설명하는 문단이에요."},{"b":[0.05,0.195,0.92,0.16],"c":[0,0.1728,1,0.2045],"r":6.52,"img":"img/U4/walk/p003_22_02.jpg","say":"모더니즘의 정의와, 바우하우스로 대표되는 독일 합리주의가 규범이라는 줄이에요."},{"b":[0.05,0.375,0.92,0.11],"c":[0,0.3278,1,0.2045],"r":6.52,"img":"img/U4/walk/p003_22_03.jpg","say":"1920년대에 국제주의 양식으로 발전한다는 문장이에요."},{"b":[0.05,0.53,0.43,0.41],"c":[0.0285,0.5095,0.473,0.451],"r":1.3984,"img":"img/U4/walk/p003_22_04.jpg","say":"왼쪽 기둥이 역사주의 기반 편이에요. 네 가지가 적혀 있어요."},{"b":[0.54,0.53,0.44,0.32],"c":[0.516,0.514,0.484,0.352],"r":1.8333,"img":"img/U4/walk/p003_22_05.jpg","say":"오른쪽 기둥이 기술문명 지향 편이에요. 다섯 가지예요."}]}},{"p":4,"title":"오귀스트 페레, 프랭클린가 아파트, 프랑스 파리, 1903","terms":["Auguste Perret","프랭클린가 아파트","cantilever","curtain wall"],"pass1":[{"kind":"say","lines":["사진 한 장과 평면도 한 장이에요.","왼쪽은 파리의 아파트 정면, 오른쪽은 그 집의 평면도예요.","**오귀스트 페레(Auguste Perret)** 가 1903년에 지은 **프랭클린가 아파트**예요.","여기서부터 벽이 무게를 안 지고 점점 얇아지기 시작해요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**캔틸레버(cantilever)**: 한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조예요.","**커튼월(curtain wall)**: 무게를 받지 않고 뼈대에 커튼처럼 걸어 놓은 바깥벽이에요.","자유로운 평면: 벽이 무게를 안 지니까 방을 마음대로 나눌 수 있는 평면이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **오귀스트 페레(Auguste Perret)**, 1874-1954년 사람이에요.","작품은 **프랭클린가 아파트**, 프랑스 파리, 1903년이에요.","신소재인 철근콘크리트로 구조를 경쾌하고 우아하게 표현했어요.","전면 파사드를 대담하게 돌출, 후퇴시켜 자유로운 평면을 구성했어요.","**캔틸레버(cantilever)** 를 적용하고 저층부를 개방적으로 디자인했어요.","지지하는 부재와 지지하지 않는 부재를 명확히 드러내 '자유로운 평면' 의 원조가 됐어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**프랭클린가 아파트**의 연도와 도시로 옳은 것은 무엇일까요?","choices":["1903년, 파리","1909년, 베를린","1911년, 알펠트"],"a":0,"why":"페레의 프랭클린가 아파트는 1903년 프랑스 파리예요."},{"kind":"english","head":"논술 답안: 프랭클린가 아파트","en":"오귀스트 페레의 프랭클린가 아파트(파리, 1903)는 철근 콘크리트로 구조를 경쾌하고 우아하게 표현하였고, 지지하는 부재와 지지하지 않는 부재를 명확히 규정하고 드러내어 자유로운 평면의 원조가 되었다.","ko":"재료(철근콘크리트), 구조 표현, 자유로운 평면 세 가지를 넣어요.","tip":"'페레는 1903, 자유로운 평면의 원조' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.48,0.045],"c":[0.026,0.0075,0.528,0.11],"r":6.4,"img":"img/U4/walk/p004_22_01.jpg","say":"제목 줄: 오귀스트 페레(Auguste Perret, 1874-1954)."},{"b":[0.04,0.12,0.92,0.3],"c":[0.0,0.104,1,0.332],"r":4.0161,"img":"img/U4/walk/p004_22_02.jpg","say":"특징 다섯 줄이에요. 철근콘크리트와 자유로운 평면이 핵심이에요."},{"b":[0.13,0.45,0.33,0.51],"c":[0.1135,0.4245,0.363,0.561],"r":0.8627,"img":"img/U4/walk/p004_22_03.jpg","say":"왼쪽 사진: 정면 가운데가 움푹 들어가고 유리창이 넓어요."},{"b":[0.49,0.49,0.37,0.46],"c":[0.4715,0.467,0.407,0.506],"r":1.0725,"img":"img/U4/walk/p004_22_04.jpg","say":"오른쪽 도면: 빛을 받으려고 가운데를 판 변형된 U자형 평면이에요."},{"b":[0.5,0.945,0.42,0.045],"c":[0.479,0.89,0.462,0.11],"r":5.6,"img":"img/U4/walk/p004_22_05.jpg","say":"캡션에 설계자, 작품, 도시, 연도가 다 적혀 있어요."}]}},{"p":5,"title":"페터 베렌스, AEG 터빈공장, 독일 베를린, 1909","terms":["페터 베렌스","AEG 터빈공장","curtain wall","합리주의"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. 길쭉한 공장 건물이 비스듬히 찍혀 있어요.","**페터 베렌스** 가 1909년 독일 베를린에 지은 **AEG 터빈공장**이에요.","앞면은 유리인데 모서리는 돌덩이처럼 두꺼워요. 이 대비가 이 건물의 전부예요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **페터 베렌스**, 작품은 **AEG 터빈공장**, 독일 베를린, 1909년이에요.","건물 전면의 **커튼월(curtain wall)**: 강철의 수직 지지 부재에 끼워진 유리 벽면이에요.","내부는 아치형 트러스로 지지해요.","육중한 모서리는 기념비적 효과를 내요. 그리스 신전을 연상시켜요.","낭만적 고전주의와 기계에 대한 **합리주의** 태도를 결합한 작품이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**AEG 터빈공장**의 육중한 모서리가 연상시키는 것은 무엇일까요?","choices":["고딕 성당","그리스 신전","로마 목욕탕"],"a":1,"why":"기념비적 효과를 내는 육중한 모서리가 그리스 신전을 연상시켜요."},{"kind":"english","head":"논술 답안: AEG 터빈공장","en":"페터 베렌스의 AEG 터빈공장(베를린, 1909)은 강철의 수직 지지 부재에 유리를 끼운 커튼월을 전면에 두고, 육중한 모서리로 그리스 신전을 연상시키는 기념비적 효과를 내어 낭만적 고전주의와 기계에 대한 합리적 태도를 결합하였다.","ko":"커튼월, 육중한 모서리, 결합 세 덩어리로 쓰면 돼요.","tip":"'베렌스 1909, 앞은 유리 옆은 돌' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.075,0.13,0.035],"c":[0.025,0.0375,0.2,0.11],"r":2.4242,"img":"img/U4/walk/p005_21_01.jpg","say":"제목: AEG 터빈공장."},{"b":[0.06,0.13,0.8,0.24],"c":[0.02,0.114,0.88,0.272],"r":4.3137,"img":"img/U4/walk/p005_21_02.jpg","say":"특징 네 줄이에요. 커튼월, 트러스, 모서리, 결합이에요."},{"b":[0.28,0.51,0.18,0.26],"c":[0.268,0.494,0.204,0.292],"r":0.9315,"img":"img/U4/walk/p005_21_03.jpg","say":"가운데 유리면이 커튼월이에요. 강철 수직 부재에 유리를 끼웠어요."},{"b":[0.44,0.52,0.14,0.35],"c":[0.41,0.5025,0.2,0.385],"r":0.6926,"img":"img/U4/walk/p005_21_04.jpg","say":"오른쪽 모서리의 두툼한 덩어리예요. 그리스 신전을 떠올리게 해요."},{"b":[0.59,0.95,0.38,0.045],"c":[0.571,0.89,0.418,0.11],"r":5.0667,"img":"img/U4/walk/p005_21_05.jpg","say":"캡션: 페터 베렌스, 독일 베를린, 1909."}]}},{"p":6,"title":"발터 그로피우스, 파구스 신발공장, 독일 알펠트, 1911","terms":["Walter Gropius","파구스 신발공장","AEG 터빈공장","curtain wall"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 위는 모서리를 가까이 찍은 것, 아래는 건물 전경이에요.","**발터 그로피우스(Walter Gropius)** 가 1911년 독일 알펠트에 지은 **파구스 신발공장**이에요.","앞 쪽의 **AEG 터빈공장**은 모서리가 두툼했죠. 여기는 모서리가 비어 있어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **발터 그로피우스(Walter Gropius)**, 독일 알펠트, 1911년이에요.","헨리 러셀 히치콕이 '1차 세계대전 이전에 세워진 가장 진보적인 작품' 이라 했어요.","형태에 대한 새로운 개념 첫째, 모서리에 기둥이 없어요.","둘째, 평탄한 외벽이 안과 밖을 구분하는 커튼 역할만 해요.","셋째, 기둥은 파사드 후면으로 후퇴해요."]},{"kind":"compare","head":"모서리로 짝지어 외우기","cols":["**AEG 터빈공장**(1909)","**파구스 신발공장**(1911)"],"rows":[["페터 베렌스, 베를린","**발터 그로피우스(Walter Gropius)**, 알펠트"],["육중한 모서리, 그리스 신전 연상","모서리에 기둥이 없고 유리가 꺾여 돌아감"],["전면은 **커튼월(curtain wall)**","외벽 전체가 커튼 역할"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"헨리 러셀 히치콕이 '1차 세계대전 이전에 세워진 가장 진보적인 작품' 이라 한 건물은 무엇일까요?","choices":["**AEG 터빈공장**","**파구스 신발공장**","**프랭클린가 아파트**"],"a":1,"why":"히치콕이 파구스 신발공장을 두고 한 평가예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'육중한 모서리로 기념비적 효과' 는 **AEG 터빈공장**이에요. **파구스 신발공장**이 아니에요.","파구스는 반대로 모서리에 기둥이 없어요. 시험에서 자주 바꿔 내요."]},{"kind":"english","head":"논술 답안: 파구스 신발공장","en":"발터 그로피우스의 파구스 신발공장(알펠트, 1911)은 모서리에 기둥이 없고, 평탄한 외벽이 내부와 외부를 구분하는 커튼 역할만 하며, 기둥은 파사드 후면으로 후퇴한 형태에 대한 새로운 개념을 보여준다.","ko":"모서리, 외벽, 기둥 세 가지를 순서대로 쓰면 돼요.","tip":"'파구스는 빈 모서리' 한 마디만 기억해요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.17,0.04],"c":[0.025,0.005,0.2,0.11],"r":2.4242,"img":"img/U4/walk/p006_22_01.jpg","say":"제목: 파구스 공장."},{"b":[0.04,0.1,0.5,0.12],"c":[0.015,0.084,0.55,0.152],"r":4.8246,"img":"img/U4/walk/p006_22_02.jpg","say":"히치콕의 평가를 인용한 줄이에요."},{"b":[0.04,0.29,0.52,0.23],"c":[0.014,0.274,0.572,0.262],"r":2.9109,"img":"img/U4/walk/p006_22_03.jpg","say":"형태에 대한 새로운 개념 세 줄이에요."},{"b":[0.55,0.12,0.44,0.37],"c":[0.516,0.1015,0.484,0.407],"r":1.5856,"img":"img/U4/walk/p006_22_04.jpg","say":"위 사진: 유리가 기둥 없이 모서리를 돌아가는 부분이에요."},{"b":[0.09,0.52,0.61,0.46],"c":[0.0595,0.494,0.671,0.506],"r":1.7681,"img":"img/U4/walk/p006_22_05.jpg","say":"아래 사진: 파구스 신발공장 전경이에요. 유리면이 반짝여요."},{"b":[0.69,0.905,0.23,0.075],"c":[0.678,0.8875,0.254,0.11],"r":3.0788,"img":"img/U4/walk/p006_22_06.jpg","say":"캡션: 발터 그로피우스, 독일 알펠트, 1911."}]}},{"p":7,"title":"독일공작연맹(Deutscher Werkbund)과 1914년 쾰른 전시회","terms":["Deutscher Werkbund","William Morris","Arts and Crafts Movement","Walter Gropius"],"pass1":[{"kind":"analogy","head":"붕어빵 틀","scene":"틀에 무늬가 복잡하면 반죽이 잘 안 빠져요. 무늬를 지우면 잘 빠져요.","map":[["복잡한 무늬 틀","손으로 만든 장식"],["무늬 없는 매끈한 틀","장식 없는 형식"],["붕어빵이 많이 나옴","기계를 이용한 양산 체제"]]},{"kind":"say","lines":["**독일공작연맹(Deutscher Werkbund)** 은 **윌리엄 모리스(William Morris)** 의 꿈은 이어받고","결론은 반대로 냈어요. 기계로 좋은 물건을 많이 만들자는 쪽이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**독일공작연맹(Deutscher Werkbund)**: 예술, 산업, 공업, 상업을 모아 기계로 좋은 제품을 만들자는 단체예요.","양산 체제: 같은 물건을 공장에서 많이 찍어 내는 방식이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["1단원 **미술공예운동(Arts and Crafts Movement)** 의 **윌리엄 모리스(William Morris)** 를 기억하죠.","예술, 공예, 산업의 합일을 제안한 그 모리스의 이상을 모델로 삼았어요.","다만 기계를 이용한 양산 체제를 수용했어요. 공업은 수준 높은 제품을 대량생산하는 효과적인 수단이에요.","예술, 산업, 공업, 상업 각계의 노력을 모아 제품의 질 향상을 목표로 했어요.","공장에서 생산하기 적합하다는 이유로 장식 없는 형식의 우월성을 강조했어요.","그래서 근대건축운동에서 장식은 불리해지고 단순하고 규칙적인 기하학 형식을 선호하게 돼요.","사진은 **발터 그로피우스(Walter Gropius)** 와 아돌프 마이어의 Werkbund Pavilion, Cologne, 1914예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**독일공작연맹(Deutscher Werkbund)** 이 장식 없는 형식의 우월성을 강조한 이유는 무엇일까요?","choices":["손으로 만들기 쉬워서","공장에서 생산하기 적합해서","값이 비싸 보여서"],"a":1,"why":"공장 생산에 적합하다는 이유였어요. 1단원 미술공예운동과 갈리는 지점이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**미술공예운동(Arts and Crafts Movement)** 의 모리스는 기계를 싫어했어요.","**독일공작연맹(Deutscher Werkbund)** 은 이상만 물려받고 기계는 받아들였어요. 결론이 반대예요."]},{"kind":"english","head":"논술 답안: 독일공작연맹","en":"독일공작연맹은 예술, 공예, 산업의 합일을 제안한 윌리엄 모리스의 이상을 모델로 하되 기계를 이용한 양산 체제를 수용하였으며, 공장에서 생산하기 적합하다는 이유에서 장식 없는 형식의 우월성을 강조하였다.","ko":"모델(모리스), 수용(기계 양산), 강조(장식 없는 형식) 세 덩어리예요.","tip":"'모리스의 꿈 + 기계의 손' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.34,0.045],"c":[0.023,0.0075,0.374,0.11],"r":4.5333,"img":"img/U4/walk/p007_22_01.jpg","say":"제목: 독일 공작연맹(Deutscher Werkbund)."},{"b":[0.04,0.12,0.93,0.27],"c":[0,0.104,1,0.302],"r":4.415,"img":"img/U4/walk/p007_22_02.jpg","say":"모리스의 이상을 모델로 하되 기계 양산을 수용한다는 문단과, 제품의 질 향상이라는 목표예요."},{"b":[0.04,0.41,0.93,0.16],"c":[0,0.3867,1,0.2067],"r":6.4506,"img":"img/U4/walk/p007_22_03.jpg","say":"장식 없는 형식이 우월하다고 강조한 이유가 적혀 있어요."},{"b":[0.14,0.57,0.72,0.39],"c":[0.104,0.5505,0.792,0.429],"r":2.4615,"img":"img/U4/walk/p007_22_04.jpg","say":"사진: 1914년 쾰른 전시회의 Werkbund Pavilion이에요."},{"b":[0.36,0.955,0.55,0.04],"c":[0.3325,0.8778,0.605,0.1222],"r":6.6012,"img":"img/U4/walk/p007_22_05.jpg","say":"캡션: 발터 그로피우스, 아돌프 마이어, Cologne, 1914."}]}},{"p":8,"title":"브루노 타우트, 독일공작연맹 유리전시관, 독일 쾰른, 1914","terms":["유리전시관","Paul Scheerbart","Deutscher Werkbund"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 왼쪽은 둥근 유리 지붕을 인 건물 외관이에요.","오른쪽은 그 안의 계단과 반짝이는 유리 벽이에요.","브루노 타우트가 1914년 독일 쾰른에 세운 **유리전시관**이에요.","같은 1914년 쾰른 전시회 작품이라 앞 쪽과 짝으로 외워요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**유리전시관**: 소설에서 영감을 얻어 유리로 지은 **독일공작연맹(Deutscher Werkbund)** 의 전시 건물이에요.","큐폴라: 건물 위에 얹은 둥근 지붕이에요. 여기서는 여러 면으로 쪼갠 다면체 큐폴라예요.","축제건축: 전시회 기간에만 쓰는 잔치용 건물이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 브루노 타우트, 독일 쾰른, 1914년이에요.","1914년 출간된 **파울 셰어바르트(Paul Scheerbart)** 의 소설 <유리건축>에서 영감을 얻었어요.","셰어바르트의 선언은 '유리가 새 시대를 열 것이다. 벽돌의 문화는 해가 될 뿐이다' 예요.","출입구는 후면에 감추어져 있고, 상부의 다면체 큐폴라 속 신성한 장소로 유도해요.","내부의 한 쌍의 계단은 '의식의 통로' 로 내려가는 출발점이에요.","내부는 채색된 유리 모자이크로 장식했어요. 고딕의 성당에서 미래의 성당으로 가는 그림이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유리전시관**이 영감을 얻은 유토피아 소설 <유리건축>의 작가는 누구일까요?","choices":["**파울 셰어바르트(Paul Scheerbart)**","**윌리엄 모리스(William Morris)**","헨리 러셀 히치콕"],"a":0,"why":"1914년 출간된 파울 셰어바르트의 소설이에요."},{"kind":"english","head":"논술 답안: 유리전시관","en":"브루노 타우트의 독일공작연맹 유리전시관(쾰른, 1914)은 파울 셰어바르트의 소설 유리건축에서 영감을 얻은 축제건축의 전형으로, 출입구를 후면에 감추고 상부의 다면체 큐폴라 속 신성한 장소로 유도하며 내부를 채색된 유리 모자이크로 장식하였다.","ko":"영감(소설), 동선(후면 출입구 → 큐폴라), 장식(채색 유리) 순서예요.","tip":"'타우트는 유리, 셰어바르트는 소설' 로 짝지어요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.035,0.25,0.035],"c":[0.0475,0,0.275,0.11],"r":3.3333,"img":"img/U4/walk/p008_22_01.jpg","say":"제목: 독일 공작연맹 유리전시관."},{"b":[0.03,0.08,0.94,0.2],"c":[0.0,0.064,1,0.232],"r":5.7471,"img":"img/U4/walk/p008_22_02.jpg","say":"셰어바르트의 소설과 선언이 적힌 문단이에요."},{"b":[0.03,0.31,0.94,0.23],"c":[0.0,0.294,1,0.262],"r":5.0891,"img":"img/U4/walk/p008_22_03.jpg","say":"출입구, 큐폴라, 계단, 유리 모자이크 설명이에요."},{"b":[0.11,0.555,0.37,0.4],"c":[0.0915,0.535,0.407,0.44],"r":1.2333,"img":"img/U4/walk/p008_22_04.jpg","say":"왼쪽 사진: 여러 면으로 쪼갠 다면체 큐폴라 외관이에요."},{"b":[0.5,0.555,0.39,0.4],"c":[0.4805,0.535,0.429,0.44],"r":1.3,"img":"img/U4/walk/p008_22_05.jpg","say":"오른쪽 사진: 채색 유리 모자이크와 한 쌍의 계단이에요."},{"b":[0.24,0.95,0.45,0.04],"c":[0.2175,0.89,0.495,0.11],"r":6.0,"img":"img/U4/walk/p008_22_06.jpg","say":"캡션: 브루노 타우트, 독일 쾰른, 1914."}]}},{"p":9,"title":"바우하우스(Bauhaus, 1919-1933)","terms":["Bauhaus","Walter Gropius","Deutscher Werkbund"],"pass1":[{"kind":"analogy","head":"요리학교","scene":"이론만 듣지 않고 주방에서 직접 만들어 보는 학교를 떠올려요.","map":[["이론 수업","색채와 조형의 기본 지식"],["주방 실습","공방에서의 공예적 실습"],["완성한 요리","형태적 완성에 대한 실습"]]},{"kind":"say","lines":["**바우하우스(Bauhaus)** 는 1919년 **발터 그로피우스(Walter Gropius)** 를 중심으로","독일 바이마르에 세워진 조형 학교예요. 1933년까지 이어져요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**바우하우스(Bauhaus)**: 예술적 창작과 공학적 기술을 통합한 조형 학교예요.","조형: 형태를 만드는 일이에요. 색채와 형태의 기본을 함께 배워요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["1919년, **발터 그로피우스(Walter Gropius)**, 독일 바이마르. 연도, 사람, 도시 세 짝이에요.","**독일공작연맹(Deutscher Werkbund)** 의 이념을 계승했어요.","색채와 조형의 기본 지식, 공예적 실습, 형태적 완성에 대한 실습을 함께 가르쳤어요.","산업화 시대 대량생산의 혜택을 대중도 누려야 한다는 사회적 의식이 있었어요.","발전된 기술이 동원된 산업생산품으로서의 건축을 지향했어요.","화가, 건축가, 공예가, 산업디자이너 전체에 영향을 준 전 유럽의 기술개혁운동이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바우하우스(Bauhaus)** 가 1919년 설립된 도시는 어디일까요?","choices":["데사우","바이마르","베를린"],"a":1,"why":"1919년 바이마르예요. 데사우는 1925년에 옮겨 간 곳이에요."},{"kind":"english","head":"논술 답안: 바우하우스","en":"바우하우스는 1919년 발터 그로피우스를 중심으로 독일 바이마르에 설립된 조형 학교로, 독일공작연맹의 이념을 계승하여 예술적 창작과 공학적 기술을 통합하였으며, 기계 시대에 적합한 디자인 교육으로 형태 교육과 공예기술교육을 병행하였다.","ko":"설립(연도, 사람, 도시), 계승(공작연맹), 교육(형태 + 공예) 세 덩어리예요.","tip":"'1919 바이마르 그로피우스' 를 한 호흡에 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.45,0.055],"c":[0.0275,0.0325,0.495,0.11],"r":6.0,"img":"img/U4/walk/p009_22_01.jpg","say":"제목: 바우하우스(Bauhaus, 1919-1933)."},{"b":[0.06,0.15,0.9,0.11],"c":[0.01,0.105,0.99,0.2],"r":6.6,"img":"img/U4/walk/p009_22_02.jpg","say":"설립 연도, 사람, 도시가 들어 있는 첫 줄이에요."},{"b":[0.06,0.27,0.9,0.055],"c":[0.01,0.1975,0.99,0.2],"r":6.6,"img":"img/U4/walk/p009_22_03.jpg","say":"독일공작연맹의 이념을 계승했다는 줄이에요."},{"b":[0.06,0.33,0.9,0.19],"c":[0.01,0.314,0.99,0.222],"r":5.9459,"img":"img/U4/walk/p009_22_04.jpg","say":"무엇을 가르쳤는지 적은 교육 내용이에요."},{"b":[0.06,0.5,0.9,0.23],"c":[0.01,0.484,0.99,0.262],"r":5.0382,"img":"img/U4/walk/p009_22_05.jpg","say":"대량생산의 혜택을 대중도 누려야 한다는 사회적 의식과, 기능주의에 의한 디자인 교육이에요."},{"b":[0.06,0.73,0.9,0.13],"c":[0.01,0.695,0.99,0.2],"r":6.6,"img":"img/U4/walk/p009_22_06.jpg","say":"전 유럽의 기술개혁운동이 되었다는 마무리예요."}]}},{"p":10,"title":"발터 그로피우스(Walter Gropius, 1883-1969)와 바우하우스 연혁","terms":["Walter Gropius","Bauhaus","데사우 바우하우스 교사"],"pass1":[{"kind":"say","lines":["왼쪽은 글, 오른쪽 파란 상자는 **바우하우스(Bauhaus)** 연혁표예요.","**발터 그로피우스(Walter Gropius)** 는 1883년에 나서 1969년에 세상을 떠났어요.","그는 학교를 물려받아 이름을 바꾸고 초대 교장이 됐어요."]}],"pass2":[{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["1919년 그로피우스는 앙리 반 데 벨데에게서 바이마르 미술공예학교 교장을 물려받았어요.","이를 1922년 **바우하우스(Bauhaus)** 라 개명하고 초대 교장이 되었어요.","건축은 그 시대의 기술에 대해 정직해야 한다고 보았어요.","새로운 건축은 새로운 기술을 경험함으로써 도달할 수 있다고 보았어요.","형태는 그 시대의 정신적, 사회적, 기술적 조건에 따라 필연적으로 발전한다고 했어요."]},{"kind":"points","head":"연혁표에서 외울 다섯 줄","items":["1919 **발터 그로피우스(Walter Gropius)** 에 의해 바우하우스가 설립되다.","1923 요하네스 이텐이 떠나고 라즐로 모홀리 나지가 오다.","1925 바우하우스, 데사우로 이동하다. 1926 건물을 완성하다.","1928 한네스 마이어가 교장이 되다. 1930 미스 반 데어 로에가 교장이 되다.","1932 데사우가 문을 닫고 베를린으로 이사. 1933 영원히 폐쇄되다."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"그로피우스가 1919년 바이마르 미술공예학교 교장을 물려받은 인물은 누구일까요?","choices":["앙리 반 데 벨데","페터 베렌스","**파울 셰어바르트(Paul Scheerbart)**"],"a":0,"why":"앙리 반 데 벨데(Henry van de Velde)에게서 물려받았어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 쪽 글은 1922년에 **바우하우스(Bauhaus)** 로 개명했다고 적어요.","같은 강의자료의 연혁표는 1919년을 설립 연도로 적어요. 시험 답은 1919년 설립이에요.","**데사우 바우하우스 교사** 는 1925년 이사, 1926년 완성으로 외워요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.46,0.05],"c":[0.017,0.01,0.506,0.11],"r":6.1333,"img":"img/U4/walk/p010_22_01.jpg","say":"제목: 발터 그로피우스(Walter Gropius, 1883-1969)."},{"b":[0.04,0.14,0.46,0.47],"c":[0.017,0.1165,0.506,0.517],"r":1.305,"img":"img/U4/walk/p010_22_02.jpg","say":"반 데 벨데에게서 학교를 물려받은 이야기와, 역사적 양식만으로는 안 된다는 인식이에요."},{"b":[0.04,0.62,0.46,0.34],"c":[0.017,0.603,0.506,0.374],"r":1.8039,"img":"img/U4/walk/p010_22_03.jpg","say":"건축은 그 시대의 기술에 정직해야 하고, 형태는 시대의 조건에서 발전한다는 문장이에요."},{"b":[0.53,0.24,0.43,0.59],"c":[0.5085,0.2105,0.473,0.649],"r":0.9718,"img":"img/U4/walk/p010_22_04.jpg","say":"오른쪽 파란 상자가 바우하우스 연혁표예요."},{"b":[0.55,0.52,0.38,0.06],"c":[0.531,0.495,0.418,0.11],"r":5.0667,"img":"img/U4/walk/p010_22_05.jpg","say":"1925 데사우로 이동, 1926 건물 완성 줄이에요."},{"b":[0.55,0.74,0.38,0.09],"c":[0.531,0.724,0.418,0.122],"r":4.5683,"img":"img/U4/walk/p010_22_06.jpg","say":"1932 베를린 이사, 1933 영원히 폐쇄 줄이에요."}]}},{"p":11,"title":"바우하우스의 세 학장: 그로피우스, 마이어, 미스","terms":["Walter Gropius","한네스 마이어","Mies van der Rohe","Bauhaus"],"pass1":[{"kind":"say","lines":["인물 사진 세 장이에요. 왼쪽부터 초대, 2대, 3대 학장이에요.","**바우하우스(Bauhaus)** 의 학장 순서는 시험 단골이에요.","'그 마 미' 세 글자로 외워요. 그로피우스, 마이어, 미스예요."]}],"pass2":[{"kind":"points","head":"세 사람의 이름과 연도","items":["초대 교장: **발터 그로피우스(Walter Gropius)**, 1883-1969.","2대 학장: **한네스 마이어**, 1889-1954. 연혁표에서는 1928년에 교장이 돼요.","3대 학장: **미스 반 데어 로에(Mies van der Rohe)**, 1886-1969. 1930년에 교장이 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바우하우스(Bauhaus)** 학장의 순서로 옳은 것은 무엇일까요?","choices":["미스, 그로피우스, 마이어","**발터 그로피우스(Walter Gropius)**, **한네스 마이어**, **미스 반 데어 로에(Mies van der Rohe)**","마이어, 미스, 그로피우스"],"a":1,"why":"그로피우스 → 한네스 마이어 → 미스 반 데어 로에 순서예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**한네스 마이어** 와 아돌프 마이어는 다른 사람이에요.","아돌프 마이어는 p.7 Werkbund Pavilion을 그로피우스와 함께 설계한 사람이에요."]}],"walk":{"head":null,"parts":[{"b":[0.015,0.24,0.28,0.64],"c":[0.001,0.208,0.308,0.704],"r":0.5833,"img":"img/U4/walk/p011_21_01.jpg","say":"왼쪽: 초대 교장 발터 그로피우스(1883-1969)."},{"b":[0.3,0.24,0.28,0.64],"c":[0.286,0.208,0.308,0.704],"r":0.5833,"img":"img/U4/walk/p011_21_02.jpg","say":"가운데: 2대 학장 한네스 마이어(1889-1954)."},{"b":[0.63,0.24,0.34,0.64],"c":[0.613,0.208,0.374,0.704],"r":0.7083,"img":"img/U4/walk/p011_21_03.jpg","say":"오른쪽: 3대 학장 미스 반 데어 로에(1886-1969)."}]}},{"p":12,"title":"요하네스 이텐(Johannes Itten, 1888-1967)과 입문 과정","terms":["Johannes Itten","Bauhaus"],"pass1":[{"kind":"say","lines":["사진과 그림이 세 장이에요. 왼쪽은 사람, 가운데는 색 연습, 오른쪽은 그림 작품이에요.","**요하네스 이텐(Johannes Itten)** 은 화가이자 교육자예요.","**바우하우스(Bauhaus)** 의 입문 과정을 이끈 사람이에요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 외울 것","items":["**요하네스 이텐(Johannes Itten)**, 1888-1967. 화가, 교육자이고 색채 이론으로 알려져 있어요.","작품 Horizontal Vertical, 1915가 오른쪽 그림이에요.","**바우하우스(Bauhaus)** 프로그램은 재료와 질감, 색상 연구에 전념하는 입문 과정으로 시작해요.","이 입문 과정이 2차원과 3차원 추상 디자인 전문 과목의 건실한 기반이 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바우하우스(Bauhaus)** 입문 과정의 기반을 만든 화가이자 교육자는 누구일까요?","choices":["**요하네스 이텐(Johannes Itten)**","라즐로 모홀리 나지","바실리 칸딘스키"],"a":0,"why":"요하네스 이텐이에요. 1923년에 떠나고 모홀리 나지가 왔어요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.07,0.47,0.045],"c":[0.0165,0.0375,0.517,0.11],"r":6.2667,"img":"img/U4/walk/p012_21_01.jpg","say":"제목: 요하네스 이텐(Johannes Itten, 1888-1967)."},{"b":[0.02,0.14,0.3,0.58],"c":[0.005,0.111,0.33,0.638],"r":0.6897,"img":"img/U4/walk/p012_21_02.jpg","say":"왼쪽 사진: 화가이자 교육자인 이텐 본인이에요."},{"b":[0.33,0.14,0.3,0.58],"c":[0.315,0.111,0.33,0.638],"r":0.6897,"img":"img/U4/walk/p012_21_03.jpg","say":"가운데: 색채 이론 연습이에요. 바탕색에 따라 가운데 색이 달라 보여요."},{"b":[0.66,0.13,0.32,0.61],"c":[0.644,0.0995,0.352,0.671],"r":0.6995,"img":"img/U4/walk/p012_21_04.jpg","say":"오른쪽: 이텐의 작품이에요. 캡션에 Horizontal Vertical, 1915라고 적혀 있어요."},{"b":[0.06,0.79,0.88,0.11],"c":[0.016,0.7472,0.968,0.1956],"r":6.5985,"img":"img/U4/walk/p012_21_05.jpg","say":"아래 문장: 입문 과정이 추상 디자인 과목의 기반이 되었다는 설명이에요."}]}},{"p":13,"title":"1919년의 바우하우스 선언문","terms":["바우하우스 선언문","Bauhaus","Walter Gropius"],"pass1":[{"kind":"say","lines":["그림 세 개와 긴 인용문이 있어요.","왼쪽은 노란 전시 포스터, 가운데는 선언문 표지의 목판화 대성당이에요.","오른쪽은 선언문 독일어 원문이고 맨 아래에 그로피우스의 서명이 있어요.","아래 한국어 글이 **바우하우스 선언문** 번역이에요."]}],"pass2":[{"kind":"points","head":"선언문에서 외울 문장","items":["'이제 미술학교들은 다시 공방과 통합되어야 한다.'","'건축가, 조각가, 화가들은 모두 공예로 돌아가야 한다. 미술은 직업이 아니기 때문이다.'","'미술가와 공예가 사이에 본질적인 차이란 존재하지 않는다.'","'계급 차별을 없애고 예술가와 공예가 사이의 차별 없는 새로운 장인의 길드를 만들자.'","슬라이드는 이 선언문을 '디자인의 혁신' 이라고 적어 두었어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"1919년 **바우하우스 선언문**의 내용으로 옳은 것은 무엇일까요?","choices":["미술가와 공예가 사이에 본질적인 차이가 있다","미술가와 공예가 사이에 본질적인 차이란 존재하지 않는다","공예는 미술보다 낮은 일이다"],"a":1,"why":"차이란 존재하지 않는다고 했어요. O, X 문제로 자주 나와요."},{"kind":"english","head":"논술 답안: 바우하우스 선언문","en":"1919년의 바우하우스 선언문은 미술학교와 공방의 통합을 주장하며, 미술가와 공예가 사이에 본질적인 차이란 존재하지 않는다고 선언하고, 계급 차별을 없앤 차별 없는 새로운 장인의 길드를 만들자고 하였다.","ko":"통합, 차이 없음, 새로운 길드 세 가지를 쓰면 돼요.","tip":"'공방으로 돌아가자, 벽을 허물자' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.05,0.37,0.68],"c":[0.0015,0.016,0.407,0.748],"r":0.7255,"img":"img/U4/walk/p013_21_01.jpg","say":"왼쪽 노란 포스터: 바우하우스 데사우 전시 포스터예요."},{"b":[0.39,0.05,0.18,0.67],"c":[0.3367,0.0165,0.2866,0.737],"r":0.5185,"img":"img/U4/walk/p013_21_02.jpg","say":"가운데 목판화: 선언문 표지에 실린 대성당 그림이에요."},{"b":[0.56,0.12,0.4,0.47],"c":[0.54,0.0965,0.44,0.517],"r":1.1348,"img":"img/U4/walk/p013_21_03.jpg","say":"오른쪽: 선언문 독일어 원문이에요. 맨 아래 서명이 그로피우스예요."},{"b":[0.71,0.75,0.25,0.04],"c":[0.6975,0.715,0.275,0.11],"r":3.3333,"img":"img/U4/walk/p013_21_04.jpg","say":"제목 줄: 1919년의 바우하우스 선언문."},{"b":[0.05,0.75,0.72,0.24],"c":[0.014,0.728,0.792,0.272],"r":3.8824,"img":"img/U4/walk/p013_21_05.jpg","say":"아래 한국어 번역이에요. 미술학교와 공방의 통합, 미술가와 공예가의 차이 대목이 핵심이에요."}]}},{"p":14,"title":"발터 그로피우스, 바우하우스 교사, 독일 데사우, 1926","terms":["데사우 바우하우스 교사","Walter Gropius","curtain wall","Bauhaus"],"pass1":[{"kind":"say","lines":["왼쪽은 1층과 2층 평면도, 오른쪽은 건물 사진이에요.","**발터 그로피우스(Walter Gropius)** 가 1926년 독일 데사우에 지은 **데사우 바우하우스 교사** 예요.","사진 오른쪽 흰 벽에 BAUHAUS 글자가 세로로 붙어 있어요.","왼쪽의 커다란 유리면이 공방동이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 도시, 연도는 **발터 그로피우스(Walter Gropius)**, 독일 데사우, 1926년이에요.","그로피우스는 과학적 사실에 의거한 객관적인 조형성을 추구했어요.","조형은 형태와 매스에 집중하고 물질성과 텍스처를 배제했어요.","건축물의 형태는 본질과 기능으로부터 도출되어야 한다는 입장이에요.","평면도를 보면 기능마다 날개가 따로 뻗어 있어요. 그래서 정면이 하나로 정해지지 않아요.","공방동에는 3층 높이의 유리 **커튼월(curtain wall)** 이 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**데사우 바우하우스 교사** 의 설계자와 연도로 옳은 것은 무엇일까요?","choices":["페터 베렌스, 1909","**발터 그로피우스(Walter Gropius)**, 1926","**미스 반 데어 로에(Mies van der Rohe)**, 1930"],"a":1,"why":"그로피우스가 1926년 독일 데사우에 완성했어요."},{"kind":"english","head":"논술 답안: 데사우 교사의 조형 원칙","en":"그로피우스는 과학적 사실에 의거한 객관적인 조형성을 추구하여 형태와 매스에 집중하고 물질성과 텍스처를 배제하였으며, 건축물의 형태는 본질과 기능으로부터 도출되어야 한다는 입장을 데사우 바우하우스 교사에서 구체화하였다.","ko":"객관적 조형성, 형태와 매스, 형태는 기능에서 세 덩어리예요.","tip":"'형태는 본질과 기능에서 나온다' 한 문장만 외워도 반은 맞아요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.065,0.17,0.04],"c":[0.045,0.03,0.2,0.11],"r":2.4242,"img":"img/U4/walk/p014_21_01.jpg","say":"제목: 바우하우스 교사."},{"b":[0.06,0.14,0.8,0.17],"c":[0.02,0.124,0.88,0.202],"r":5.8086,"img":"img/U4/walk/p014_21_02.jpg","say":"형태는 본질과 기능에서 나와야 한다는 그로피우스의 입장이에요."},{"b":[0.01,0.39,0.42,0.52],"c":[0,0.364,0.462,0.572],"r":1.0769,"img":"img/U4/walk/p014_21_03.jpg","say":"왼쪽: 1층과 2층 평면이에요. 기능마다 날개가 뻗어 있어요."},{"b":[0.43,0.39,0.55,0.51],"c":[0.395,0.3645,0.605,0.561],"r":1.4379,"img":"img/U4/walk/p014_21_04.jpg","say":"오른쪽 사진: 데사우 교사 전경이에요. 장식 하나 없는 흰 벽이에요."},{"b":[0.55,0.48,0.17,0.36],"c":[0.535,0.462,0.2,0.396],"r":0.6734,"img":"img/U4/walk/p014_21_05.jpg","say":"공방동의 3층 높이 유리 커튼월이에요."},{"b":[0.5,0.945,0.47,0.045],"c":[0.4765,0.89,0.517,0.11],"r":6.2667,"img":"img/U4/walk/p014_21_06.jpg","say":"캡션: 발터 그로피우스, 독일 데사우, 1926."}]}},{"p":15,"title":"바우하우스 교사의 외관: 유리 커튼월과 띠창, 장식 없는 흰 벽","terms":["데사우 바우하우스 교사","curtain wall","Walter Gropius","Bauhaus"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 왼쪽은 잔디밭에서 본 전경, 오른쪽은 유리벽을 올려다본 모습이에요.","**발터 그로피우스(Walter Gropius)** 의 **데사우 바우하우스 교사**, 1926년이에요.","앞 쪽에 이어 같은 건물을 계속 봐요. 이번에는 외관이 주제예요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["1926년에 완성된 건물은 평면과 미학적 표현 모두에서 **바우하우스(Bauhaus)** 의 이상을 구체화한 건물군이에요.","인상적인 외관은 두 가지의 결합이에요.","하나는 공방 건물의 3층 높이 유리 **커튼월(curtain wall)** 이에요.","다른 하나는 커다란 띠를 이루는 유리창들이 있는 그 밖의 날개 부분들이에요.","벽은 완전히 아무 장식도 없는 하얀 벽으로 디자인했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**데사우 바우하우스 교사** 의 공방 건물에 있는 것은 무엇일까요?","choices":["3층 높이 유리 **커튼월(curtain wall)**","육중한 돌 모서리","다면체 큐폴라"],"a":0,"why":"공방 건물의 3층 높이 유리 커튼월이 이 건물의 얼굴이에요."},{"kind":"english","head":"논술 답안: 데사우 교사의 외관","en":"데사우 바우하우스 교사의 인상적인 외관은 공방 건물의 3층 높이 유리 커튼월과 커다란 띠를 이루는 유리창들이 있는 그 밖의 날개 부분들의 결합이며, 완전히 아무 장식도 없는 하얀 벽으로 디자인되었다.","ko":"공방동 커튼월, 날개의 띠창, 장식 없는 흰 벽 세 가지를 쓰면 돼요.","tip":"'유리 한 덩어리 + 띠창 날개 + 흰 벽' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.92,0.11],"c":[0.0,0,1,0.2045],"r":6.52,"img":"img/U4/walk/p015_21_01.jpg","say":"1926년 완성. 바우하우스의 이상을 구체화한 건물군이라는 문장이에요."},{"b":[0.04,0.16,0.92,0.11],"c":[0.0,0.1128,1,0.2045],"r":6.52,"img":"img/U4/walk/p015_21_02.jpg","say":"인상적인 외관: 3층 높이 유리 커튼월 + 띠를 이루는 유리창의 결합이에요."},{"b":[0.04,0.28,0.5,0.05],"c":[0.015,0.2494,0.55,0.1111],"r":6.6007,"img":"img/U4/walk/p015_21_03.jpg","say":"완전히 아무 장식도 없는 하얀 벽이라는 한 줄이에요."},{"b":[0.035,0.355,0.59,0.58],"c":[0.0055,0.326,0.649,0.638],"r":1.3563,"img":"img/U4/walk/p015_21_04.jpg","say":"왼쪽 사진: 전경이에요. 가운데 큰 유리면이 공방 건물이에요."},{"b":[0.635,0.31,0.35,0.62],"c":[0.615,0.279,0.385,0.682],"r":0.7527,"img":"img/U4/walk/p015_21_05.jpg","say":"오른쪽 사진: 유리벽을 올려다본 모습. BAUHAUS 글자가 붙어 있어요."},{"b":[0.54,0.955,0.42,0.04],"c":[0.519,0.89,0.462,0.11],"r":5.6,"img":"img/U4/walk/p015_21_06.jpg","say":"캡션: 발터 그로피우스, 바우하우스 교사, 독일 데사우, 1926."}]}},{"p":16,"title":"거대하게 빛나는 유리상자, 그리고 정면이 없는 건물","terms":["데사우 바우하우스 교사","curtain wall","Adolf Loos","Arts and Crafts Movement"],"pass1":[{"kind":"analogy","head":"반짝이는 상자","scene":"밤에 불을 켠 유리 진열장을 밖에서 보면 속이 다 비쳐요.","map":[["유리 진열장","유리 파사드"],["속이 다 비치는 모습","거대하게 빛나는 '유리상자'"],["어느 쪽에서 봐도 앞면","'정면' 이 없음"]]},{"kind":"say","lines":["같은 **데사우 바우하우스 교사** 를 두 방향에서 찍은 사진 두 장이에요.","왼쪽은 유리면 쪽, 오른쪽은 발코니가 줄지어 있는 기숙사 날개예요.","같은 건물인데 얼굴이 달라요. 그래서 정면이 하나로 정해지지 않아요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["새로운 공학적 처리는 새로운 철과 유리라는 재료에서 오는 투명함의 아름다움이에요.","유리 파사드는 전체 건물을 거대하게 빛나는 '유리상자' 처럼 보이게 해요.","외부 관찰자에게는 그때까지 어떤 건물에서도 경험하지 못한 경이로움을 주었어요.","기념비적이고 과장된 표현은 배제했어요.","'정면' 이 없어요. 기능 표현과 큐비즘적 미학이 완벽하게 조화를 이뤄요.","장식 없는 흰 벽은 3단원 **아돌프 로스(Adolf Loos)** 의 '장식은 죄악' 과 이어지는 태도예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**데사우 바우하우스 교사** 에 대한 설명으로 옳은 것은 무엇일까요?","choices":["뚜렷한 정면 하나를 중심으로 설계했다","'정면' 이 없고 기능 표현과 큐비즘적 미학이 조화를 이룬다","기념비적이고 과장된 표현을 강조했다"],"a":1,"why":"정면이 없다는 점이 핵심이에요. O, X 문제로 자주 나와요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["1단원 **미술공예운동(Arts and Crafts Movement)** 은 손으로 만든 장식을 아꼈어요.","여기는 정반대예요. 장식을 완전히 지우고 유리와 흰 벽만 남겨요.","이 태도의 앞 선수가 **아돌프 로스(Adolf Loos)** 예요. 주문을 다시 외워요. 싫어 → 새 장식 → 정리 → 없애."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.08,0.9,0.05],"c":[0.005,0.005,0.99,0.2],"r":6.6,"img":"img/U4/walk/p016_21_01.jpg","say":"새로운 공학적 처리: 철과 유리에서 오는 투명함의 아름다움이에요."},{"b":[0.05,0.14,0.92,0.11],"c":[0,0.0928,1,0.2045],"r":6.52,"img":"img/U4/walk/p016_21_02.jpg","say":"유리 파사드가 건물을 거대하게 빛나는 유리상자로 보이게 한다는 문장이에요."},{"b":[0.05,0.26,0.4,0.05],"c":[0.03,0.23,0.44,0.11],"r":5.3333,"img":"img/U4/walk/p016_21_03.jpg","say":"기념비적, 과장된 표현은 배제했다는 한 줄이에요."},{"b":[0.05,0.31,0.7,0.05],"c":[0.015,0.2572,0.77,0.1556],"r":6.5981,"img":"img/U4/walk/p016_21_04.jpg","say":"'정면' 이 없다는 핵심 한 줄이에요. 큐비즘적 미학과의 조화예요."},{"b":[0.01,0.41,0.46,0.46],"c":[0,0.387,0.506,0.506],"r":1.3333,"img":"img/U4/walk/p016_21_05.jpg","say":"왼쪽 사진: 공방 건물의 유리면을 비스듬히 본 모습이에요."},{"b":[0.51,0.41,0.47,0.46],"c":[0.483,0.387,0.517,0.506],"r":1.3623,"img":"img/U4/walk/p016_21_06.jpg","say":"오른쪽 사진: 발코니가 줄지어 있는 기숙사 날개예요."}]}},{"p":17,"title":"유리 파사드와 시-공간(space-time), 모호이 나지의 가시성","terms":["space-time","데사우 바우하우스 교사","모더니즘","curtain wall"],"pass1":[{"kind":"say","lines":["실내 사진 두 장이에요. 유리벽이 이어진 복도와 창가예요.","유리벽을 따라 걸으면 바깥 풍경과 건물이 겹쳐 보여요.","이 경험에 붙은 이름이 **시-공간(space-time)** 이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**시-공간(space-time)**: 유리 파사드를 따라 걸으며 중첩된 뷰를 경험하는 것이에요.","중첩된 뷰: 유리 너머 풍경과 건물이 겹쳐 보이는 화면이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["건물의 유리 파사드는 표면을 따라 걷게 해서 사용자에게 중첩된 뷰를 제공해요.","지그프리드 기디온이 이를 건축에서의 진정한 **시-공간(space-time)** 적용 사례라고 평가했어요.","건축에서 시각적인 요소, 즉 광학의 위생성과 건강함을 뜻하는 가시성이 중요해요.","이 가시성은 **모더니즘** 사고에서 중심적 역할을 차지해요. 말한 사람은 L. 모호이 너지예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**데사우 바우하우스 교사** 의 유리 파사드를 '건축에서의 진정한 **시-공간(space-time)** 적용 사례' 라고 평가한 사람은 누구일까요?","choices":["L. 모호이 너지","지그프리드 기디온","헨리 러셀 히치콕"],"a":1,"why":"지그프리드 기디온(Sigfried Giedion)이에요. 모호이 너지는 가시성 이야기예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["기디온은 **시-공간(space-time)**, 모호이 너지는 가시성이에요. 두 사람을 바꿔 내기 쉬워요.","히치콕은 p.6 파구스 공장 평가와 p.25 국제주의 양식 책의 사람이에요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.1,0.92,0.16],"c":[0,0.0778,1,0.2045],"r":6.52,"img":"img/U4/walk/p017_22_01.jpg","say":"유리 파사드가 중첩된 뷰를 준다는 문장과 기디온의 평가예요."},{"b":[0.05,0.27,0.92,0.09],"c":[0,0.2128,1,0.2045],"r":6.52,"img":"img/U4/walk/p017_22_02.jpg","say":"모호이 너지의 가시성 이야기예요."},{"b":[0.02,0.475,0.455,0.48],"c":[0,0.451,0.5005,0.528],"r":1.2639,"img":"img/U4/walk/p017_22_03.jpg","say":"왼쪽 사진: 유리 복도예요. 바깥 건물과 유리가 겹쳐 보여요."},{"b":[0.51,0.475,0.47,0.48],"c":[0.483,0.451,0.517,0.528],"r":1.3056,"img":"img/U4/walk/p017_22_04.jpg","say":"오른쪽 사진: 실내에서 본 유리벽이에요. 창살이 격자로 나뉘어요."}]}},{"p":18,"title":"그로피우스의 Housing Units, 1923","terms":["Housing Units","Walter Gropius","Bauhaus"],"pass1":[{"kind":"analogy","head":"레고 블록","scene":"같은 블록 몇 가지로 서로 다른 집을 여러 채 만들 수 있어요.","map":[["기본 블록 여섯 개","기본 공간단위"],["조합하는 방법","다양한 조합으로 만든 기본 주거타입"],["내가 고르는 즐거움","거주자의 취향에 따른 구성"]]},{"kind":"say","lines":["왼쪽은 흰 상자들이 겹친 집 사진, 오른쪽은 덩어리를 더하는 그림이에요.","**발터 그로피우스(Walter Gropius)** 의 **Housing Units** 예요. 1923년에 제시했어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**Housing Units**: 기본 공간단위를 조합해 표준 주거타입을 만드는 방식이에요.","가변성: 사는 사람이 바꿔 쓸 수 있는 여지예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["새로운 건축의 원칙은 다섯 가지예요.","정확히 재단된 형태, 여러 가지의 단순함, 기능에 따른 구성이에요.","그리고 전형적인 기본 형태로의 제한, 그것들의 연속과 반복이에요.","1923년에 기본 공간단위를 다양하게 조합해 가장 전형적 유형이면서 최대한의 가변성이 보장되는 기본 주거타입들을 제시했어요.","부재와 요소를 선택할 수 있게 열어 두면 생산의 효율성이 보장돼요.","동시에 거주자는 개인의 취향에 따라 자기 주거공간을 구성할 수 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**Housing Units** 에서 기본 공간단위를 조합해 기본 주거타입들을 제시한 해는 언제일까요?","choices":["1919년","1923년","1926년"],"a":1,"why":"1923년이에요. 1926년은 데사우 교사 완성이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.28,0.035],"c":[0.036,0.0025,0.308,0.11],"r":3.7333,"img":"img/U4/walk/p018_22_01.jpg","say":"제목: 그로피우스의 Housing Units."},{"b":[0.03,0.1,0.55,0.51],"c":[0.0025,0.0745,0.605,0.561],"r":1.4379,"img":"img/U4/walk/p018_22_02.jpg","say":"왼쪽 사진: 상자를 겹쳐 놓은 듯한 흰 집이에요."},{"b":[0.59,0.095,0.39,0.52],"c":[0.5705,0.069,0.429,0.572],"r":1.0,"img":"img/U4/walk/p018_22_03.jpg","say":"오른쪽 그림: 기본 덩어리를 더해 집을 만드는 다이어그램이에요."},{"b":[0.06,0.64,0.9,0.09],"c":[0.01,0.585,0.99,0.2],"r":6.6,"img":"img/U4/walk/p018_22_04.jpg","say":"새로운 건축의 원칙 다섯 가지가 적힌 문단이에요."},{"b":[0.06,0.76,0.9,0.08],"c":[0.01,0.7,0.99,0.2],"r":6.6,"img":"img/U4/walk/p018_22_05.jpg","say":"1923년 기본 주거타입들을 제시했다는 문장이에요."},{"b":[0.06,0.87,0.9,0.1],"c":[0.01,0.8,0.99,0.2],"r":6.6,"img":"img/U4/walk/p018_22_06.jpg","say":"효율성과 거주자의 선택을 함께 보장한다는 마무리예요."}]}},{"p":19,"title":"마이스터 주택: 비용 절감과 공기 단축을 계산한 박스","terms":["마이스터 주택","Walter Gropius","Bauhaus","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. 흰 상자들이 어긋나게 겹친 집이에요.","2층에 커다란 유리창이 상자처럼 튀어나와 있어요.","**바우하우스(Bauhaus)** 교수들이 살던 **마이스터 주택** 이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**마이스터 주택**: 바우하우스 교수(마이스터)들을 위해 지은 주택이에요.","공기: 공사에 걸리는 기간이에요. 공기 단축은 공사를 빨리 끝내는 것이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["건축계획과 시공, 실내 인테리어까지 완벽한 기술적 해결과정을 거쳐 완성했어요.","특히 박스 형태와 디테일은 비용 절감과 공기 단축을 염두에 둔 수학적 계산의 결과예요.","건물뿐 아니라 그 안에서의 생활까지 '근대적 삶' 에 걸맞도록 조직했어요.","그 생활이 건강하고 충만하며 경제적이고 합리적으로 영위될 수 있게 했어요.","장식이 하나도 없는 흰 상자예요. **아돌프 로스(Adolf Loos)** 가 말한 방향 그대로예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**마이스터 주택** 의 박스 형태와 디테일이 겨냥한 것은 무엇일까요?","choices":["시공 과정의 비용 절감과 공기 단축","손으로 만든 장식의 아름다움","그리스 신전 같은 기념비성"],"a":0,"why":"수학적 계산으로 비용과 공사 기간을 줄이려 한 결과예요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.05,0.17,0.035],"c":[0.055,0.0125,0.2,0.11],"r":2.4242,"img":"img/U4/walk/p019_22_01.jpg","say":"제목: 마이스터하우스."},{"b":[0.06,0.11,0.92,0.14],"c":[0,0.0778,1,0.2045],"r":6.52,"img":"img/U4/walk/p019_22_02.jpg","say":"박스 형태와 디테일이 수학적 계산의 결과라는 문장이에요."},{"b":[0.06,0.28,0.8,0.05],"c":[0.02,0.2161,0.88,0.1778],"r":6.5992,"img":"img/U4/walk/p019_22_03.jpg","say":"그 안에서의 생활까지 근대적 삶에 맞게 조직했다는 줄이에요."},{"b":[0.06,0.34,0.92,0.08],"c":[0,0.2778,1,0.2045],"r":6.52,"img":"img/U4/walk/p019_22_04.jpg","say":"건강하고 충만하며 경제적이고 합리적인 생활을 목표로 했어요."},{"b":[0.21,0.41,0.56,0.58],"c":[0.182,0.362,0.616,0.638],"r":1.2874,"img":"img/U4/walk/p019_22_05.jpg","say":"사진: 흰 상자들이 어긋나게 겹쳐 있어요. 2층 유리창이 튀어나와요."}]}},{"p":20,"title":"마이스터 주택(그로피우스 자택)의 외관, 실내, 평면","terms":["마이스터 주택","Walter Gropius","Bauhaus"],"pass1":[{"kind":"say","lines":["사진 두 장과 평면도 두 장이에요.","위 왼쪽은 집의 바깥, 위 오른쪽은 그 집 안이에요.","캡션에 '바우하우스 교수들을 위한 **마이스터 주택**(그로피우스 자택)' 이라고 적혀 있어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["지붕이 평평하고 처마가 없어요. 벽은 매끈한 흰 면이에요.","1층 모서리는 유리로 크게 열려 있고 2층 덩어리가 그 위에 얹혀 있어요.","실내 사진에는 벽을 따라 짠 책장과 강철 파이프로 만든 의자가 보여요.","아래 평면 두 장은 **발터 그로피우스(Walter Gropius)** 자택의 1층과 2층이에요.","실내 인테리어까지 함께 계획한 집이라 가구도 같은 기하학 언어예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**마이스터 주택** 은 누구를 위해 지은 집일까요?","choices":["**바우하우스(Bauhaus)** 교수들","공장 노동자들","베를린 시민들"],"a":0,"why":"마이스터는 바우하우스의 교수를 뜻해요. 그로피우스 자택도 그중 하나예요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.03,0.47,0.45],"c":[0,0.0075,0.517,0.495],"r":1.3926,"img":"img/U4/walk/p020_21_01.jpg","say":"왼쪽 사진: 외관이에요. 평평한 지붕과 매끈한 흰 벽이에요."},{"b":[0.5,0.03,0.48,0.45],"c":[0.472,0.0075,0.528,0.495],"r":1.4222,"img":"img/U4/walk/p020_21_02.jpg","say":"오른쪽 사진: 실내예요. 붙박이 책장과 강철 파이프 의자가 있어요."},{"b":[0.49,0.49,0.46,0.035],"c":[0.467,0.4525,0.506,0.11],"r":6.1333,"img":"img/U4/walk/p020_21_03.jpg","say":"캡션: 바우하우스 교수들을 위한 마이스터 주택(그로피우스 자택)."},{"b":[0.05,0.59,0.78,0.39],"c":[0.011,0.5705,0.858,0.429],"r":2.6667,"img":"img/U4/walk/p020_21_04.jpg","say":"아래: 그로피우스 자택의 1층과 2층 평면이에요."}]}},{"p":21,"title":"평평한 지붕, 매끈한 벽체, 인방 없는 창 (파울 클레와 칸딘스키 2호 연립주택)","terms":["마이스터 주택","인방","Expressionism","Walter Gropius","Arts and Crafts Movement"],"pass1":[{"kind":"say","lines":["사진 두 장과 평면 두 장이에요. 숲 속에 선 흰 집이에요.","캡션은 '**마이스터 주택**(파울 클레와 칸딘스키를 위한 2호 연립주택)' 이에요.","지붕에 처마가 없고 창이 벽과 같은 면으로 딱 붙어 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**인방**: 창 위에 가로로 걸친 부재예요. 보통은 창 위에 턱처럼 드러나요.","처마: 지붕이 벽 밖으로 튀어나온 부분이에요. 여기에는 없어요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["평평한 지붕과 매끈한 벽체가 먼저 보여요.","처마나 **인방** 없이 창이 벽체와 한 표면을 이뤄요. 벽에 그림을 붙인 것처럼 평평해요.","이것은 **발터 그로피우스(Walter Gropius)** 가 **표현주의(Expressionism)** 적 성향에서 완전히 탈피했음을 보여줘요.","동시에 공예적 수단을 멀리하기 시작했다는 뜻이에요. **미술공예운동(Arts and Crafts Movement)** 과 멀어지는 순간이에요.","아래 평면 두 장을 보면 같은 집 두 채가 붙은 연립주택이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**마이스터 주택** 의 창이 보여주는 것은 무엇일까요?","choices":["처마와 **인방** 을 크게 드러내 장식했다","처마나 **인방** 없이 벽체와 한 표면을 이룬다","창 위에 아치를 얹었다"],"a":1,"why":"처마나 인방 없이 벽과 한 면을 이루는 창이에요. 표현주의에서 탈피한 증거예요."},{"kind":"english","head":"논술 답안: 마이스터 주택의 특징","en":"마이스터 주택의 평지붕과 매끈한 벽체, 그리고 처마나 인방 없이 벽체와 한 표면을 이루는 창은 그로피우스가 표현주의적 성향에서 완전히 탈피하여 공예적 수단을 멀리하기 시작했음을 보여준다.","ko":"지붕, 벽, 창 세 가지를 들고 마지막에 표현주의 탈피로 맺어요.","tip":"'평지붕 + 매끈한 벽 + 인방 없는 창' 세 박자로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.92,0.14],"c":[0,0.0178,1,0.2045],"r":6.52,"img":"img/U4/walk/p021_22_01.jpg","say":"평지붕, 매끈한 벽체, 인방 없는 창이 표현주의 탈피의 증거라는 문장이에요."},{"b":[0.03,0.215,0.41,0.44],"c":[0.0095,0.193,0.451,0.484],"r":1.2424,"img":"img/U4/walk/p021_22_02.jpg","say":"왼쪽 사진: 처마가 없어요. 벽과 창이 한 면을 이뤄요."},{"b":[0.48,0.205,0.48,0.45],"c":[0.456,0.1825,0.528,0.495],"r":1.4222,"img":"img/U4/walk/p021_22_03.jpg","say":"오른쪽 사진: 세로로 긴 창이 벽면과 같은 면으로 붙어 있어요."},{"b":[0.04,0.675,0.36,0.075],"c":[0.022,0.6575,0.396,0.11],"r":4.8,"img":"img/U4/walk/p021_22_04.jpg","say":"캡션: 파울 클레와 칸딘스키를 위한 2호 연립주택이에요."},{"b":[0.36,0.7,0.62,0.29],"c":[0.318,0.678,0.682,0.322],"r":2.824,"img":"img/U4/walk/p021_22_05.jpg","say":"아래: 2호 연립주택 평면 두 장이에요. 같은 집 두 채가 붙어 있어요."}]}},{"p":22,"title":"색을 칠한 계단실 사진 (글자 없는 슬라이드)","terms":["마이스터 주택","Bauhaus"],"pass1":[{"kind":"say","lines":["이 슬라이드에는 글자가 하나도 없어요. 사진만 세 장이에요.","앞 쪽 **마이스터 주택** 이야기에 이어지는 사진 슬라이드예요.","캡션이 없어서 어느 집인지 슬라이드가 말해 주지 않아요.","그래서 보이는 것만 설명할게요. 계단과 복도에 색이 칠해져 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["세 장 모두 계단과 복도를 찍은 실내 사진이에요.","위 가운데 사진은 바닥이 짙은 초록, 벽이 파랑, 계단 옆면이 노랑, 손잡이가 빨강이에요.","오른쪽 사진은 천장이 짙은 보라, 벽이 하늘색, 문틀이 노랑이에요.","아래 사진은 벽이 크림색, 문틀이 노랑, 계단 난간이 파랑이에요.","면마다 다른 색을 칠해 공간이 색 면들의 조합처럼 보여요.","**바우하우스(Bauhaus)** 가 색채를 기초 과목으로 가르쳤다는 점을 떠올리며 보면 좋아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 설계자도 연도도 적혀 있지 않아요.","시험에서 이 사진만 보고 건물 이름을 단정하지 말고, 색 면 구성이라는 특징만 기억하세요."]}],"walk":{"head":null,"parts":[{"b":[0.33,0.03,0.24,0.43],"c":[0.318,0.0085,0.264,0.473],"r":0.7442,"img":"img/U4/walk/p022_21_01.jpg","say":"위 가운데 사진: 초록 바닥, 파란 벽, 노란 계단 옆면, 빨간 손잡이예요."},{"b":[0.59,0.03,0.4,0.63],"c":[0.56,0,0.44,0.693],"r":0.8466,"img":"img/U4/walk/p022_21_02.jpg","say":"오른쪽 사진: 짙은 보라 천장과 하늘색 벽, 노란 문틀이에요."},{"b":[0.08,0.475,0.49,0.49],"c":[0.0555,0.4505,0.539,0.539],"r":1.3333,"img":"img/U4/walk/p022_21_03.jpg","say":"아래 사진: 크림색 벽에 노란 문틀, 파란 계단 난간이에요."}]}},{"p":23,"title":"발터 그로피우스, 한자지구 아파트 블록, 독일 베를린, 1957","terms":["Walter Gropius","Bauhaus"],"pass1":[{"kind":"say","lines":["사진 두 장과 평면 두 장이에요. 건물이 부드럽게 휘어 있어요.","**발터 그로피우스(Walter Gropius)** 의 한자지구 아파트 블록이에요.","독일 베를린, 1957년이에요. **바우하우스(Bauhaus)** 시절보다 훨씬 뒤의 작품이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 도시, 연도는 **발터 그로피우스(Walter Gropius)**, 독일 베를린, 1957년이에요.","발코니가 둥근 띠처럼 층마다 이어져 있어요.","건물 전체가 활처럼 휘어 있어요. 평면도에서도 같은 곡선이 보여요.","1층은 기둥으로 띄워서 아래를 지나다닐 수 있게 했어요.","1926년 데사우 교사의 직선 상자와 달리 곡선을 쓴 후기작이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"한자지구 아파트 블록의 설계자와 연도로 옳은 것은 무엇일까요?","choices":["**발터 그로피우스(Walter Gropius)**, 1957","**리처드 노이트라(Richard Neutra)**, 1929","**미스 반 데어 로에(Mies van der Rohe)**, 1930"],"a":0,"why":"그로피우스가 1957년 독일 베를린에 지었어요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.045,0.49,0.49],"c":[0.0055,0.0205,0.539,0.539],"r":1.3333,"img":"img/U4/walk/p023_21_01.jpg","say":"왼쪽 위 사진: 둥근 띠 모양 발코니가 층층이 붙어 있어요."},{"b":[0.525,0.045,0.45,0.85],"c":[0.5025,0.0025,0.495,0.935],"r":0.7059,"img":"img/U4/walk/p023_21_02.jpg","say":"오른쪽 사진: 건물 전체가 휘어 있고 1층은 기둥으로 띄웠어요."},{"b":[0.04,0.56,0.43,0.3],"c":[0.0185,0.544,0.473,0.332],"r":1.8996,"img":"img/U4/walk/p023_21_03.jpg","say":"왼쪽 아래: 휘어진 평면 두 장이에요."},{"b":[0.22,0.945,0.47,0.04],"c":[0.1965,0.89,0.517,0.11],"r":6.2667,"img":"img/U4/walk/p023_21_04.jpg","say":"캡션: 발터 그로피우스, 한자지구 아파트 블록, 독일 베를린, 1957."}]}},{"p":24,"title":"발터 그로피우스, 베를린의 바우하우스 아카이브, 독일 베를린, 1979","terms":["Walter Gropius","Bauhaus"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 반원통 모양 지붕이 여러 개 줄지어 솟아 있어요.","**발터 그로피우스(Walter Gropius)** 의 베를린 **바우하우스(Bauhaus)** 아카이브예요.","독일 베를린, 1979년이에요. 그로피우스의 작품 목록에서 가장 늦은 것이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 도시, 연도는 **발터 그로피우스(Walter Gropius)**, 독일 베를린, 1979년이에요.","지붕이 반원통 모양이고 한쪽이 잘린 채 하늘을 향해 열려 있어요.","벽은 흰 금속판을 격자로 붙여 마감했어요.","건물 사이를 경사로가 이어 주고 있어요.","**바우하우스(Bauhaus)** 의 자료를 모아 두는 기록관이라 이름이 아카이브예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"베를린의 **바우하우스(Bauhaus)** 아카이브가 세워진 해는 언제일까요?","choices":["1926년","1957년","1979년"],"a":2,"why":"1979년이에요. 1926년은 데사우 교사, 1957년은 한자지구 아파트 블록이에요."}],"walk":{"head":null,"parts":[{"b":[0.17,0.02,0.64,0.44],"c":[0.138,0,0.704,0.484],"r":1.9394,"img":"img/U4/walk/p024_21_01.jpg","say":"위 사진: 반원통 지붕이 여러 개 줄지어 솟아 있어요."},{"b":[0.17,0.47,0.64,0.47],"c":[0.138,0.4465,0.704,0.517],"r":1.8156,"img":"img/U4/walk/p024_21_02.jpg","say":"아래 사진: 같은 지붕을 가까이서 본 모습이에요. 벽은 흰 금속판이에요."},{"b":[0.2,0.955,0.55,0.04],"c":[0.1725,0.8778,0.605,0.1222],"r":6.6012,"img":"img/U4/walk/p024_21_03.jpg","say":"캡션: 발터 그로피우스, 베를린의 바우하우스 아카이브, 독일 베를린, 1979."}]}},{"p":25,"title":"국제주의와 기능주의","terms":["internationale Architektur","International Style","Functionalism","Walter Gropius","Bauhaus","Arts and Crafts Movement","모더니즘"],"pass1":[{"kind":"analogy","head":"어느 나라나 똑같은 매장","scene":"주방 동선을 효율로만 짜면 어느 나라 매장이든 비슷해져요.","map":[["효율만 따진 주방","기능과 기술을 그대로 따르는 설계"],["어느 나라나 닮은 매장","**국제주의 건축(internationale Architektur)**"],["쓰임새가 겉으로 드러남","**기능주의(Functionalism)**"]]},{"kind":"say","lines":["이 쪽은 글만 있어요. 위는 국제주의 건축, 아래는 기능주의 건축이에요.","1단원 **미술공예운동(Arts and Crafts Movement)** 에서 시작한 긴 흐름이 여기서 한 양식으로 굳어져요.","**모더니즘** 이 나라 경계를 넘어 하나의 이름을 갖는 순간이라고 보면 돼요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**국제주의 건축(internationale Architektur)**: 그로피우스가 1925년 바우하우스 총서 1권 표제로 쓴 용어예요.","**국제주의 양식(International Style)**: 히치콕과 존슨의 1932년 책으로 굳어진 양식 이름이에요.","**기능주의(Functionalism)**: 건물의 목적이 되는 사용과 기능을 형태가 그대로 표현하는 건축이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**발터 그로피우스(Walter Gropius)** 는 1925년 **바우하우스(Bauhaus)** 아카데미가 간행한 총서 1권의 표제로 이 용어를 채택했어요.","그리고 이를 자신의 건축활동의 강령으로 삼았어요.","1932년 미국에서 베네와 그로피우스의 내용을 토대로 책이 나와요.","헨리 러셀 히치콕과 필립 존슨의 '**국제주의 양식(International Style)** : 1922년 이후의 건축' 이에요.","**기능주의(Functionalism)** 는 좋은 디자인의 미학이 특정한 형태에 있지 않다고 봐요.","테크놀로지를 스스로 재현함으로써 편리하고 강하고 효율적인 삶을 보장한다고 봐요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"1932년 '**국제주의 양식(International Style)** : 1922년 이후의 건축' 을 펴낸 사람은 누구일까요?","choices":["**발터 그로피우스(Walter Gropius)** 와 베네","헨리 러셀 히치콕과 필립 존슨","지그프리드 기디온과 모호이 너지"],"a":1,"why":"히치콕과 존슨이에요. 용어를 먼저 쓴 사람은 1925년의 그로피우스예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["용어를 처음 쓴 사람(1925 그로피우스)과 양식 이름으로 굳힌 책(1932 히치콕, 존슨)을 바꿔 내기 쉬워요.","**국제주의 건축(internationale Architektur)** 은 용어, **국제주의 양식(International Style)** 은 책 이름에서 온 양식 이름이에요."]},{"kind":"english","head":"논술 답안: 국제주의 건축","en":"그로피우스는 1925년 바우하우스 총서 1권의 표제로 국제주의 건축이라는 용어를 채택하였고, 1932년 히치콕과 필립 존슨의 국제주의 양식 : 1922년 이후의 건축이 출간됨으로써 새로운 양식의 용어로 자리잡았다.","ko":"1925년 용어 채택, 1932년 책 출간 두 덩어리로 나눠 쓰면 돼요.","tip":"'25는 그로피우스, 32는 히치콕과 존슨' 으로 외워요."},{"kind":"english","head":"논술 답안: 기능주의 건축","en":"기능주의의 형태는 하나의 구조가 만들어질 때 그것의 목적이 되는 사용 및 기능을 그대로 표현하며, 좋은 디자인의 미학은 특정한 형태가 아니라 테크놀로지를 스스로 재현하는 데 있다.","ko":"형태가 기능을 그대로 표현한다는 것이 정의예요.","tip":"'쓰임새가 곧 생김새' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.27,0.05],"c":[0.0365,0.02,0.297,0.11],"r":3.6,"img":"img/U4/walk/p025_22_01.jpg","say":"제목: 국제주의와 기능주의."},{"b":[0.06,0.15,0.42,0.045],"c":[0.039,0.1175,0.462,0.11],"r":5.6,"img":"img/U4/walk/p025_22_02.jpg","say":"소제목: 국제주의 건축(International Architecture)."},{"b":[0.06,0.21,0.92,0.15],"c":[0,0.1828,1,0.2045],"r":6.52,"img":"img/U4/walk/p025_22_03.jpg","say":"1925년 총서 1권 표제로 용어를 채택했다는 문장이에요."},{"b":[0.06,0.38,0.92,0.2],"c":[0,0.364,1,0.232],"r":5.7471,"img":"img/U4/walk/p025_22_04.jpg","say":"1932년 히치콕과 존슨의 책으로 양식 용어가 되었다는 문장이에요."},{"b":[0.06,0.63,0.36,0.045],"c":[0.042,0.5975,0.396,0.11],"r":4.8,"img":"img/U4/walk/p025_22_05.jpg","say":"소제목: 기능주의 건축(Functionalism)."},{"b":[0.06,0.69,0.92,0.27],"c":[0,0.674,1,0.302],"r":4.415,"img":"img/U4/walk/p025_22_06.jpg","say":"기능주의 설명 두 문단이에요. 기능을 그대로 표현한다는 대목이 핵심이에요."}]}},{"p":26,"title":"리차드 노이트라, 로벨 하우스(Health House), 미국 로스 앤젤레스, 1929","terms":["Richard Neutra","Lovell House","International Style","internationale Architektur"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 왼쪽은 옛 사진, 오른쪽은 지금의 모습이에요.","**리처드 노이트라(Richard Neutra)** 의 **로벨 하우스(Lovell House)** 예요.","미국 로스 앤젤레스, 1929년이고 Health House라고도 불러요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 도시, 연도는 **리처드 노이트라(Richard Neutra)**, 미국 로스 앤젤레스, 1929년이에요.","넓은 유리 부분들과 장식이 없는 흰 벽면이 보여요.","이것이 노이트라의 **국제주의 양식(International Style)** 성향을 보여줘요.","이 스틸 프레임의 주택은 대부분 카탈로그에서 고른 구성 요소들로 만들어졌어요.","철골구조의 입체 기하학적 건물이에요. 비탈에 층층이 걸쳐 있어요.","**국제주의 건축(internationale Architektur)** 이 미국으로 건너간 사례로 외우면 좋아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**로벨 하우스(Lovell House)** 에 대한 설명으로 옳은 것은 무엇일까요?","choices":["벽돌을 손으로 쌓아 만든 주택","구성 요소 대부분을 카탈로그에서 고른 스틸 프레임 주택","다면체 큐폴라를 얹은 전시 건물"],"a":1,"why":"카탈로그에서 고른 구성 요소로 만든 스틸 프레임 주택이에요."},{"kind":"english","head":"논술 답안: 로벨 하우스","en":"리처드 노이트라의 로벨 하우스(로스앤젤레스, 1929)는 넓은 유리 부분들과 장식이 없는 흰 벽면으로 국제주의 성향을 보여주며, 대부분 카탈로그에서 고른 구성 요소들로 만들어진 스틸 프레임의 철골구조 입체 기하학적 건물이다.","ko":"유리와 흰 벽, 카탈로그 부품, 철골구조 세 가지를 쓰면 돼요.","tip":"'노이트라 1929, 카탈로그로 지은 집' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.07,0.5,0.045],"c":[0.015,0.0369,0.55,0.1111],"r":6.6007,"img":"img/U4/walk/p026_21_01.jpg","say":"제목: 리처드 노이트라(Richard Neutra, 1892-1970)."},{"b":[0.05,0.155,0.22,0.045],"c":[0.038,0.1225,0.244,0.11],"r":2.9576,"img":"img/U4/walk/p026_21_02.jpg","say":"작품 이름: 로벨 하우스 Lovell House."},{"b":[0.05,0.22,0.88,0.17],"c":[0.006,0.204,0.968,0.202],"r":6.3894,"img":"img/U4/walk/p026_21_03.jpg","say":"넓은 유리, 카탈로그 부품, 철골구조 세 줄이에요."},{"b":[0.03,0.42,0.55,0.49],"c":[0.0025,0.3955,0.605,0.539],"r":1.4966,"img":"img/U4/walk/p026_21_04.jpg","say":"왼쪽 사진: 비탈에 층층이 걸린 집이에요. 가는 기둥과 넓은 유리가 보여요."},{"b":[0.6,0.4,0.34,0.58],"c":[0.583,0.362,0.374,0.638],"r":0.7816,"img":"img/U4/walk/p026_21_05.jpg","say":"오른쪽 사진: 지금의 모습이에요. 안내판에 HEALTH HOUSE라고 적혀 있어요."},{"b":[0.03,0.92,0.56,0.04],"c":[0.002,0.8755,0.616,0.1245],"r":6.5971,"img":"img/U4/walk/p026_21_06.jpg","say":"캡션: 리차드 노이트라, 로벨 하우스(Health House), 1929."}]}},{"p":27,"title":"로벨 하우스의 실내와 층별 평면","terms":["Lovell House","Richard Neutra"],"pass1":[{"kind":"say","lines":["사진 두 장과 평면 세 장이에요. 앞 쪽과 같은 **로벨 하우스(Lovell House)** 예요.","이번에는 안에서 본 모습이에요. 벽 대신 유리창이 이어져 있어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["위 사진은 거실이에요. 벽 자리를 유리창이 채워서 바깥 나무가 다 보여요.","아래 사진은 계단 옆 공간이에요. 큰 유리창으로 빛이 깊이 들어와요.","창살이 가는 금속으로 되어 있어 기둥이 거의 안 보여요.","오른쪽 평면 세 장은 층별 평면이에요. 비탈을 따라 층이 어긋나 있어요.","**리처드 노이트라(Richard Neutra)** 의 1929년 작품이라는 캡션이 아래에 다시 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.05,0.02,0.51,0.44],"c":[0.0245,0,0.561,0.484],"r":1.5455,"img":"img/U4/walk/p027_21_01.jpg","say":"위 사진: 거실이에요. 유리창이 이어져 바깥 나무가 다 보여요."},{"b":[0.05,0.48,0.51,0.46],"c":[0.0245,0.457,0.561,0.506],"r":1.4783,"img":"img/U4/walk/p027_21_02.jpg","say":"아래 사진: 계단 옆 공간이에요. 큰 유리창으로 빛이 들어와요."},{"b":[0.6,0.11,0.36,0.79],"c":[0.582,0.0705,0.396,0.869],"r":0.6076,"img":"img/U4/walk/p027_21_03.jpg","say":"오른쪽: 층별 평면 세 장이에요. 비탈을 따라 층이 어긋나요."},{"b":[0.22,0.955,0.57,0.04],"c":[0.1915,0.8733,0.627,0.1267],"r":6.5983,"img":"img/U4/walk/p027_21_04.jpg","say":"캡션: 리차드 노이트라, 로벨 하우스(Health House), 1929."}]}},{"p":28,"title":"리처드 노이트라, 카우프만 저택, 팜 스프링스, 미국 캘리포니아, 1947","terms":["카우프만 저택","Richard Neutra","Mies van der Rohe","International Style","Lovell House"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 왼쪽은 데크와 벽난로, 오른쪽은 수영장 쪽에서 본 집이에요.","**리처드 노이트라(Richard Neutra)** 의 **카우프만 저택** 이에요.","미국 캘리포니아 팜 스프링스, 1947년이에요. **로벨 하우스(Lovell House)** 보다 18년 뒤 작품이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 도시, 연도는 **리처드 노이트라(Richard Neutra)**, 팜 스프링스, 1947년이에요.","**국제주의 양식(International Style)** 의 단순성이 후기 작품에서도 이어져요.","**카우프만 저택** 에서는 **미스 반 데어 로에(Mies van der Rohe)** 의 영향을 볼 수 있어요.","커다란 유리 부분들과 바닥, 천장의 단순한 처리가 특징이에요.","그래서 실내 공간이 주의 깊게 계획된 외부의 정원 부분들과 함께 통일성을 가져요.","지붕이 길게 뻗어 나와 실내와 바깥 데크가 한 공간처럼 이어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카우프만 저택** 에서 영향을 볼 수 있다고 한 건축가는 누구일까요?","choices":["**미스 반 데어 로에(Mies van der Rohe)**","**발터 그로피우스(Walter Gropius)**","페터 베렌스"],"a":0,"why":"노이트라의 후기작 카우프만 저택에서 미스 반 데어 로에의 영향이 보인다고 했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**로벨 하우스(Lovell House)** 는 1929년 로스 앤젤레스, **카우프만 저택** 은 1947년 팜 스프링스예요.","둘 다 **리처드 노이트라(Richard Neutra)** 작품이라 연도와 도시를 바꿔 내기 쉬워요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.14,0.9,0.1],"c":[0,0.09,0.99,0.2],"r":6.6,"img":"img/U4/walk/p028_21_01.jpg","say":"국제주의 양식의 단순성이 후기작에도 이어지고 미스의 영향이 보인다는 문장이에요."},{"b":[0.04,0.26,0.92,0.1],"c":[0.0,0.2078,1,0.2045],"r":6.52,"img":"img/U4/walk/p028_21_02.jpg","say":"커다란 유리와 단순한 바닥, 천장이 실내와 정원을 묶는다는 문장이에요."},{"b":[0.01,0.4,0.43,0.36],"c":[0,0.382,0.473,0.396],"r":1.5926,"img":"img/U4/walk/p028_21_03.jpg","say":"왼쪽 사진: 지붕이 뻗어 나와 실내와 바깥 데크가 이어져요."},{"b":[0.46,0.4,0.49,0.36],"c":[0.4355,0.382,0.539,0.396],"r":1.8148,"img":"img/U4/walk/p028_21_04.jpg","say":"오른쪽 사진: 수영장 쪽에서 본 모습이에요. 유리벽이 정원과 실내를 이어요."},{"b":[0.04,0.78,0.54,0.04],"c":[0.013,0.74,0.594,0.12],"r":6.6,"img":"img/U4/walk/p028_21_05.jpg","say":"캡션: 리처드 노이트라, 카우프만 저택, 팜 스프링스, 미국 캘리포니아, 1947."}]}},{"p":29,"title":"데 스테일(De Stijl), 1917년 네덜란드 로테르담","terms":["De Stijl","Bauhaus","Art Nouveau","Functionalism"],"pass1":[{"kind":"analogy","head":"몬드리안 그림을 건물로","scene":"검은 직선 격자 안에 빨강, 파랑, 노랑 칸이 있는 그림을 떠올려요.","map":[["검은 직선 격자","서로 교차하는 직선과 면"],["빨강, 파랑, 노랑 칸","적색, 청색, 황색"],["바탕의 흰색과 회색","백색, 흑색, 회색"]]},{"kind":"say","lines":["**데 스테일(De Stijl)** 은 1917년 네덜란드 로테르담에서 발간된 잡지 이름이에요.","그 잡지로 모인 화가, 건축가, 조각가 집단에서 시작했어요.","2단원 **아르 누보(Art Nouveau)** 의 구불구불한 곡선을 떠올려 보세요. 여기는 정반대로 직선만 써요.","주문을 다시 외워요. 싫어 → 새 장식 → 정리 → 없애."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**데 스테일(De Stijl)**: 직선과 면, 3원색과 무채색만 쓰는 네덜란드 예술 운동이에요.","기계미학: 자연이 아니라 기계에서 아름다움의 기준을 찾는 태도예요.","**기능주의(Functionalism)**: 쓰임새를 형태가 그대로 보여 주는 건축이에요. p.25에서 봤어요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["1917년, 네덜란드 로테르담, 잡지 '데 스테일'. 연도와 도시와 매체를 한 묶음으로 외워요.","기능에 따른 단순성과 절대 조화를 추구해요. **기능주의(Functionalism)** 와 결이 같아요.","디자인 요소를 절제하고 서로 교차하는 직선과 면의 조합으로 추상적 형태를 만들어요.","백색, 흑색, 회색과 대비를 이루는 적색, 청색, 황색을 써요. 여섯 색만 쓰는 셈이에요.","창단선언은 '자연과 대립하는 기계미학을 건축의 근본으로 할 것' 이에요.","독일에는 **바우하우스(Bauhaus)**, 네덜란드에는 **데 스테일(De Stijl)** 이 있다고 짝지어 외워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**데 스테일(De Stijl)** 이 시작된 잡지가 발간된 해와 도시는 어디일까요?","choices":["1917년, 네덜란드 로테르담","1919년, 독일 바이마르","1924년, 네덜란드 위트레흐트"],"a":0,"why":"1917년 네덜란드 로테르담에서 발간된 잡지예요."},{"kind":"check","q":"**데 스테일(De Stijl)** 의 창단선언 내용은 무엇일까요?","choices":["자연을 구축형태의 원형으로 삼을 것","자연과 대립하는 기계미학을 건축의 근본으로 할 것","장식은 죄악이다"],"a":1,"why":"자연과 대립하는 기계미학을 건축의 근본으로 하자는 선언이에요."},{"kind":"english","head":"논술 답안: 데 스테일","en":"데 스테일은 1917년 네덜란드 로테르담에서 발간된 잡지를 통하여 모인 화가, 건축가, 조각가 집단에서 시작하였으며, 서로 교차하는 직선과 면의 조합으로 이루어지는 추상적 형태를 추구하였다.","ko":"여기에 '백색, 흑색, 회색과 대비를 이루는 적색, 청색, 황색' 한 구절을 덧붙이면 완성이에요.","tip":"'17년 잡지, 직선, 여섯 색' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.25,0.05],"c":[0.0375,0.03,0.275,0.11],"r":3.3333,"img":"img/U4/walk/p029_22_01.jpg","say":"제목: 데 스테일(De Stijl)."},{"b":[0.04,0.15,0.93,0.1],"c":[0,0.0967,1,0.2067],"r":6.4506,"img":"img/U4/walk/p029_22_02.jpg","say":"1917년 네덜란드 로테르담에서 발간된 잡지에서 시작했다는 문장이에요."},{"b":[0.04,0.27,0.4,0.05],"c":[0.02,0.24,0.44,0.11],"r":5.3333,"img":"img/U4/walk/p029_22_03.jpg","say":"기능에 따른 단순성, 절대 조화 추구라는 한 줄이에요."},{"b":[0.04,0.33,0.93,0.11],"c":[0,0.2817,1,0.2067],"r":6.4506,"img":"img/U4/walk/p029_22_04.jpg","say":"직선과 면, 3원색과 무채색이라는 형태 언어 설명이에요."},{"b":[0.02,0.56,0.34,0.19],"c":[0.003,0.544,0.374,0.222],"r":2.2462,"img":"img/U4/walk/p029_22_05.jpg","say":"파란 네모 안이 창단선언이에요. 자연과 대립하는 기계미학이 근본이에요."},{"b":[0.36,0.44,0.29,0.55],"c":[0.3455,0.395,0.319,0.605],"r":0.703,"img":"img/U4/walk/p029_22_06.jpg","say":"가운데 포스터: 마름모 안에 검은 직선과 3원색 칸이 있어요."}]}},{"p":30,"title":"피트 몬드리안과 신조형주의","terms":["Piet Mondrian","신조형주의","De Stijl","Theo Van Doesburg"],"pass1":[{"kind":"say","lines":["그림판 하나, 사람 사진 하나, 그림 하나가 있어요.","**피트 몬드리안(Piet Mondrian)**, 1871-1944년 사람이에요.","오른쪽 그림이 그의 화면 구성이에요. 직선과 무채색, 3원색만 있어요."]},{"kind":"analogy","head":"상자를 펼쳐 판자로","scene":"종이 상자를 펼치면 입체가 납작한 판이 되죠.","map":[["납작해진 판","2차원의 면"],["원래 상자","3차원의 볼륨"],["펼치는 일","**신조형주의**의 환원"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**신조형주의**: 형태와 색의 추상적 가치가 우월하다는 이론이에요.","환원: 복잡한 것을 더 단순한 것으로 바꾸는 일이에요.","순수 추상: 무엇을 그린 것인지 알아볼 필요 없이 형태와 색만 남긴 그림이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**데 스테일(De Stijl)** 은 회화와 조각에서 순수 추상의 컨셉들에 관심을 가졌어요.","실증주의보다 추상적인 형태가 주요 관심사가 됐어요.","**피트 몬드리안(Piet Mondrian)** 과 **테오 반 두스뷔르흐(Theo Van Doesburg)** 가 **신조형주의** 이론을 발전시켰어요.","자연적이고 주관적인 모든 가치 중에서 형태와 색상의 추상적 가치가 우월하다고 주장했어요.","색상은 원색들과 검정색이에요.","방법은 3차원의 볼륨을 새로운 조형요소, 즉 2차원의 면으로 환원하는 것이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**신조형주의** 이론을 발전시킨 두 사람은 누구일까요?","choices":["**피트 몬드리안(Piet Mondrian)** 과 **테오 반 두스뷔르흐(Theo Van Doesburg)**","리트펠트와 오우트","그로피우스와 마이어"],"a":0,"why":"몬드리안과 반 두스뷔르흐예요. 3차원 볼륨을 2차원의 면으로 환원해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**신조형주의** 와 4단원 앞쪽의 신즉물주의는 이름만 비슷해요.","신조형주의는 **데 스테일(De Stijl)** 의 이론, 신즉물주의는 독일의 반 표현주의 전위예술이에요."]}],"walk":{"head":null,"parts":[{"b":[0.06,0.05,0.9,0.1],"c":[0.01,0,0.99,0.2],"r":6.6,"img":"img/U4/walk/p030_22_01.jpg","say":"데 스테일이 순수 추상에 관심을 가졌다는 두 줄이에요."},{"b":[0.06,0.17,0.92,0.15],"c":[0,0.1428,1,0.2045],"r":6.52,"img":"img/U4/walk/p030_22_02.jpg","say":"몬드리안과 반 두스뷔르흐가 신조형주의를 발전시켰다는 문단이에요."},{"b":[0.06,0.34,0.7,0.05],"c":[0.025,0.2872,0.77,0.1556],"r":6.5981,"img":"img/U4/walk/p030_22_03.jpg","say":"3차원 볼륨을 2차원의 면으로 환원한다는 핵심 한 줄이에요."},{"b":[0.06,0.41,0.39,0.58],"c":[0.0405,0.362,0.429,0.638],"r":0.8966,"img":"img/U4/walk/p030_22_04.jpg","say":"왼쪽 그림판과 그 아래 두 줄이에요. 3원색과 무채색 정리, 몬드리안의 이름표가 적혀 있어요."},{"b":[0.52,0.655,0.16,0.29],"c":[0.5,0.639,0.2,0.322],"r":0.8282,"img":"img/U4/walk/p030_22_05.jpg","say":"가운데 사진: 피트 몬드리안 본인이에요."},{"b":[0.69,0.41,0.29,0.52],"c":[0.6755,0.384,0.319,0.572],"r":0.7436,"img":"img/U4/walk/p030_22_06.jpg","say":"오른쪽 그림: 검은 직선 격자 안에 빨강, 노랑, 파랑 칸이 있어요."}]}},{"p":31,"title":"야코부스 J. P. 오우트, 카페 더 우니의 파사드 그림","terms":["Jacobus J. P. Oud","카페 더 우니","De Stijl"],"pass1":[{"kind":"say","lines":["커다란 그림 한 장이에요. 건물 정면을 그린 그림이에요.","**야코부스 J. P. 오우트(Jacobus J. P. Oud)** 의 **카페 더 우니** 예요.","**데 스테일(De Stijl)** 그림을 그대로 건물 앞면에 붙인 것처럼 보여요."]}],"pass2":[{"kind":"points","head":"이 그림에서 볼 것","items":["설계자는 **야코부스 J. P. 오우트(Jacobus J. P. Oud)**, 1890-1963년 사람이에요.","파사드를 종, 횡의 직선으로 분할했어요. 가로선과 세로선으로 면을 나눈다는 뜻이에요.","나뉜 면을 원색으로 채색했어요. 빨강, 파랑, 노랑이 보여요.","상점 로고의 그래픽적 디자인도 특징이에요. CAFE DE UNIE 글자가 면의 하나처럼 쓰여요.","글자와 색 면과 창이 같은 격자 위에 놓여 하나의 그림이 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카페 더 우니** 의 파사드 특징이 아닌 것은 무엇일까요?","choices":["종, 횡의 직선으로 분할","원색으로 채색","곡선 장식과 꽃 무늬"],"a":2,"why":"곡선 장식은 아르 누보의 특징이에요. 데 스테일은 직선과 원색이에요."}],"walk":{"head":null,"parts":[{"b":[0.43,0.04,0.51,0.045],"c":[0.4045,0.0058,0.561,0.1133],"r":6.6019,"img":"img/U4/walk/p031_21_01.jpg","say":"제목: 야코부스 J. P. 오우트(Jacobus J. P. Oud, 1890-1963)."},{"b":[0.59,0.19,0.14,0.045],"c":[0.56,0.1575,0.2,0.11],"r":2.4242,"img":"img/U4/walk/p031_21_02.jpg","say":"작품 이름: 카페 더 우니."},{"b":[0.58,0.28,0.38,0.17],"c":[0.561,0.264,0.418,0.202],"r":2.7591,"img":"img/U4/walk/p031_21_03.jpg","say":"특징 세 줄: 직선 분할, 원색 채색, 상점 로고의 그래픽적 디자인이에요."},{"b":[0.06,0.09,0.5,0.3],"c":[0.035,0.074,0.55,0.332],"r":2.2088,"img":"img/U4/walk/p031_21_04.jpg","say":"그림 위쪽: 노란 테두리에 검은 바탕, DE UNIE 글자가 크게 붙어 있어요."},{"b":[0.06,0.29,0.5,0.3],"c":[0.035,0.274,0.55,0.332],"r":2.2088,"img":"img/U4/walk/p031_21_05.jpg","say":"가운데: 빨간 면과 작은 창 다섯 개가 가로로 줄지어요."},{"b":[0.06,0.6,0.5,0.38],"c":[0.035,0.581,0.55,0.418],"r":1.7544,"img":"img/U4/walk/p031_21_06.jpg","say":"아래: 파란 면과 큰 유리창이에요. 왼쪽 세로 간판도 파랑이에요."}]}},{"p":32,"title":"야코부스 J. P. 오우트, 카페 더 우니, 네덜란드 로테르담, 1925","terms":["Jacobus J. P. Oud","카페 더 우니"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 앞 쪽 그림이 실제로 지어진 모습이에요.","**야코부스 J. P. 오우트(Jacobus J. P. Oud)** 의 **카페 더 우니**, 네덜란드 로테르담, 1925년이에요.","양옆 건물은 옛날 벽돌집이라 이 집만 그림처럼 튀어 보여요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 작품, 도시, 연도는 **야코부스 J. P. 오우트(Jacobus J. P. Oud)**, **카페 더 우니**, 네덜란드 로테르담, 1925년이에요.","위쪽 DE UNIE 글자판이 노란 띠에 얹혀 있어요.","가운데 붉은 면, 아래 파란 유리창 띠가 가로로 층을 이뤄요.","왼쪽에 CAFE RESTAURANT 세로 간판, 오른쪽에 DE UNIE 세로 간판이 붙어 있어요.","간판까지 면 구성의 일부로 계획한 것이 이 건물의 핵심이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카페 더 우니** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["네덜란드 로테르담, 1925","네덜란드 위트레흐트, 1924","프랑스 스트라스부르, 1928"],"a":0,"why":"오우트의 카페 더 우니는 1925년 로테르담이에요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.06,0.47,0.84],"c":[0.0065,0.018,0.517,0.924],"r":0.746,"img":"img/U4/walk/p032_21_01.jpg","say":"왼쪽 사진: 실제로 지어진 카페 더 우니의 정면이에요."},{"b":[0.52,0.08,0.46,0.82],"c":[0.494,0.039,0.506,0.902],"r":0.748,"img":"img/U4/walk/p032_21_02.jpg","say":"오른쪽 사진: 비스듬히 본 모습이에요. 옆 건물들은 옛 벽돌집이에요."},{"b":[0.47,0.93,0.48,0.04],"c":[0.446,0.89,0.528,0.11],"r":6.4,"img":"img/U4/walk/p032_21_03.jpg","say":"캡션: 야코부스 J. P. 오우트, 카페 더 우니, 네덜란드 로테르담, 1925."}]}},{"p":33,"title":"헤리트 리트펠트, 슈뢰더 하우스, 네덜란드 위트레흐트, 1924","terms":["Gerrit Rietveld","슈뢰더 하우스","De Stijl"],"pass1":[{"kind":"say","lines":["큰 사진 한 장과 작은 사진, 스케치가 있어요.","**헤리트 리트펠트(Gerrit Rietveld)** 의 **슈뢰더 하우스** 예요.","네덜란드 위트레흐트, 1924년이에요. **데 스테일(De Stijl)** 의 대표작이에요.","흰 판과 회색 면이 서로 어긋나게 겹쳐 있어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **헤리트 리트펠트(Gerrit Rietveld)**, 1888-1964년 사람이에요.","작품은 **슈뢰더 하우스**, 네덜란드 위트레흐트, 1924년이에요.","의뢰인은 트루스 슈뢰더(Truss Schröder)예요. 오른쪽 위 사진이 그 사람이에요.","벽이 하나의 덩어리로 보이지 않고 판들이 따로따로 떠 있는 것처럼 보여요.","노란 기둥 하나가 벽에서 떨어져 수직으로 서 있어요. 구조가 아니라 선 하나로 보여요.","발코니 난간은 가는 검은 선이에요. 면과 선과 색만으로 집을 만들었어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**슈뢰더 하우스** 의 설계자, 도시, 연도로 옳은 것은 무엇일까요?","choices":["**야코부스 J. P. 오우트(Jacobus J. P. Oud)**, 로테르담, 1925","**헤리트 리트펠트(Gerrit Rietveld)**, 위트레흐트, 1924","**테오 반 두스뷔르흐(Theo Van Doesburg)**, 스트라스부르, 1928"],"a":1,"why":"리트펠트, 위트레흐트, 1924년이에요. 데 스테일 세 작품의 연도를 붙여 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.08,0.45,0.045],"c":[0.0175,0.0475,0.495,0.11],"r":6.0,"img":"img/U4/walk/p033_21_01.jpg","say":"제목: 헤리트 리트펠트(Gerrit Rietveld, 1888-1964)."},{"b":[0.01,0.145,0.7,0.71],"c":[0,0.1095,0.77,0.781],"r":1.3146,"img":"img/U4/walk/p033_21_02.jpg","say":"큰 사진: 슈뢰더 하우스 전경이에요. 판들이 어긋나게 겹쳐요."},{"b":[0.13,0.19,0.2,0.45],"c":[0.118,0.1675,0.224,0.495],"r":0.6034,"img":"img/U4/walk/p033_21_03.jpg","say":"노란 기둥 하나가 벽에서 떨어져 수직으로 서 있어요."},{"b":[0.79,0.14,0.13,0.33],"c":[0.755,0.1235,0.2,0.363],"r":0.7346,"img":"img/U4/walk/p033_21_04.jpg","say":"오른쪽 위: 의뢰인 트루스 슈뢰더의 사진이에요."},{"b":[0.74,0.49,0.24,0.37],"c":[0.728,0.4715,0.264,0.407],"r":0.8649,"img":"img/U4/walk/p033_21_05.jpg","say":"오른쪽 아래: 입면과 평면 스케치예요. 빨강, 노랑, 파랑 점이 찍혀 있어요."},{"b":[0.21,0.87,0.47,0.045],"c":[0.1865,0.8375,0.517,0.11],"r":6.2667,"img":"img/U4/walk/p033_21_06.jpg","say":"캡션: 헤리트 리트펠트, 슈뢰더 하우스, 네덜란드 위트레흐트, 1924."}]}},{"p":34,"title":"슈뢰더 하우스의 다섯 가지 특징과 평면","terms":["슈뢰더 하우스","Gerrit Rietveld","De Stijl","Art Nouveau"],"pass1":[{"kind":"say","lines":["오른쪽 위는 집의 모형 사진, 아래는 평면도 세 장이에요.","**슈뢰더 하우스** 의 특징 다섯 줄이 왼쪽에 적혀 있어요.","핵심은 '판이 떠 있다' 와 '칸막이로 공간을 바꾼다' 두 가지예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["구성파: 면과 선으로 입체를 짜 맞추는 예술 흐름이에요.","유동적 공간: 벽으로 딱 나누지 않고 필요에 따라 바뀌는 공간이에요.","구조 그리드: 기둥과 보가 만드는 네모난 뼈대 격자예요."]},{"kind":"points","head":"다섯 가지 특징, 그대로 외우기","items":["구성파다운 입체 오브제 창조.","칸막이벽으로 유동적 공간 구성.","자유로운 창의 구성, 과감한 색상 도입.","다양한 판이 수직 수평의 3차원의 좌표에 부유.","구조 그리드를 적게 사용하는 대신 채색된 면들의 구성 선호."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**슈뢰더 하우스** 에 대한 설명으로 옳은 것은 무엇일까요?","choices":["구조 그리드를 많이 쓰고 채색된 면은 피했다","구조 그리드를 적게 쓰는 대신 채색된 면들의 구성을 선호했다","벽돌을 손으로 쌓아 물결치는 벽을 만들었다"],"a":1,"why":"구조 그리드를 적게 쓰고 채색된 면의 구성을 선호했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["2단원 **아르 누보(Art Nouveau)** 는 자연의 곡선을 썼어요.","**데 스테일(De Stijl)** 의 **슈뢰더 하우스** 는 자연을 부정하고 직선과 면만 써요. 정반대예요."]},{"kind":"english","head":"논술 답안: 슈뢰더 하우스","en":"헤리트 리트펠트의 슈뢰더 하우스(위트레흐트, 1924)는 구성파다운 입체 오브제로, 칸막이벽으로 유동적 공간을 구성하고 자유로운 창과 과감한 색상을 도입하였으며, 다양한 판이 수직 수평의 3차원 좌표에 부유하도록 하였다.","ko":"다섯 특징 중 세 가지만 확실히 써도 점수가 나와요.","tip":"'판이 떠 있다, 칸막이로 바꾼다' 두 마디를 먼저 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.13,0.035],"c":[0.005,0.0025,0.2,0.11],"r":2.4242,"img":"img/U4/walk/p034_22_01.jpg","say":"제목: 슈뢰더 하우스."},{"b":[0.03,0.15,0.44,0.2],"c":[0.008,0.134,0.484,0.232],"r":2.7816,"img":"img/U4/walk/p034_22_02.jpg","say":"앞 세 줄: 입체 오브제, 유동적 공간, 자유로운 창과 과감한 색상이에요."},{"b":[0.03,0.33,0.44,0.24],"c":[0.008,0.314,0.484,0.272],"r":2.3725,"img":"img/U4/walk/p034_22_03.jpg","say":"뒤 두 줄: 판이 3차원 좌표에 부유하고 채색된 면을 쓴다는 설명이에요."},{"b":[0.46,0.075,0.53,0.52],"c":[0.417,0.049,0.583,0.572],"r":1.359,"img":"img/U4/walk/p034_22_04.jpg","say":"오른쪽: 집의 모형 사진이에요. 노란 기둥과 빨강, 파랑 선이 보여요."},{"b":[0.02,0.6,0.33,0.33],"c":[0.0035,0.5835,0.363,0.363],"r":1.3333,"img":"img/U4/walk/p034_22_05.jpg","say":"아래 왼쪽 평면: 2층 칸막이가 접힌 상태, 1924."},{"b":[0.36,0.6,0.62,0.33],"c":[0.318,0.5835,0.682,0.363],"r":2.5051,"img":"img/U4/walk/p034_22_06.jpg","say":"아래 가운데와 오른쪽: 1층 평면도와 2층 평면도, 1924."}]}},{"p":35,"title":"슈뢰더 하우스의 위층: 슬라이딩 판넬과 분해된 입방체","terms":["슈뢰더 하우스","Gerrit Rietveld"],"pass1":[{"kind":"say","lines":["실내 사진 두 장이에요. 같은 자리를 조금 다르게 찍었어요.","**슈뢰더 하우스** 위층의 메인 리빙플로어예요.","바닥에 빨강, 파랑 색 면이 칠해져 있고 빨강 파랑 의자가 놓여 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["보이드(void): 벽이 비어 있는 구멍 자리예요. 여기에 유리를 끼워요.","새시(sash): 유리를 끼우는 창틀이에요. 여기서는 금속 새시예요.","슬라이딩 판넬: 밀어서 여닫는 칸막이 판이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["선으로 둘러싸인 블록으로 벽과 지붕, 돌출된 데크들의 평면이 복잡하게 서로 꿰뚫고 있어요.","보이드들은 금속 새시에 유리가 끼워져 있어요.","위층의 메인 리빙플로어는 슬라이딩 판넬들로 된 시스템으로 나뉘어요.","그래서 다양한 정도의 열림을 갖도록 재배열될 수 있어요. 낮에는 한 방, 밤에는 여러 방이에요.","무한한 공간의 일부로서 동적으로 자유롭게 분해된 순수한 입방체라고 정리해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**슈뢰더 하우스** 위층의 메인 리빙플로어를 나누는 것은 무엇일까요?","choices":["벽돌 벽","슬라이딩 판넬들로 된 시스템","유리 커튼월"],"a":1,"why":"밀어서 여닫는 슬라이딩 판넬이에요. 그래서 공간이 유동적이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.08,0.92,0.09],"c":[0,0.0228,1,0.2045],"r":6.52,"img":"img/U4/walk/p035_22_01.jpg","say":"벽과 지붕, 데크가 서로 꿰뚫고 보이드에 유리가 끼워져 있다는 문장이에요."},{"b":[0.05,0.2,0.92,0.09],"c":[0,0.1428,1,0.2045],"r":6.52,"img":"img/U4/walk/p035_22_02.jpg","say":"위층 메인 리빙플로어가 슬라이딩 판넬로 나뉜다는 문장이에요."},{"b":[0.05,0.31,0.7,0.05],"c":[0.015,0.2572,0.77,0.1556],"r":6.5981,"img":"img/U4/walk/p035_22_03.jpg","say":"자유롭게 분해된 순수한 입방체라는 마무리예요."},{"b":[0.03,0.395,0.5,0.51],"c":[0.005,0.3695,0.55,0.561],"r":1.3072,"img":"img/U4/walk/p035_22_04.jpg","say":"왼쪽 사진: 위층 실내예요. 빨강, 파랑 바닥 면과 색 의자가 보여요."},{"b":[0.53,0.395,0.45,0.51],"c":[0.505,0.3695,0.495,0.561],"r":1.1765,"img":"img/U4/walk/p035_22_05.jpg","say":"오른쪽 사진: 같은 자리를 조금 다르게 찍은 사진이에요."}]}},{"p":36,"title":"슈뢰더 하우스의 층별 평면과 실내 (글자 설명이 없는 슬라이드)","terms":["슈뢰더 하우스"],"pass1":[{"kind":"say","lines":["설명 글이 없는 슬라이드예요. 도면 두 장과 사진 두 장만 있어요.","앞 쪽에서 이어지는 **슈뢰더 하우스** 의 도면과 실내예요.","왼쪽 파란 도면은 옛날 청사진이라 선이 흰색으로 보여요."]}],"pass2":[{"kind":"points","head":"도면에서 보이는 글자","items":["위 도면에는 studio, working, sleeping, reading, hall, kitchen-dining-living, w.c. 가 적혀 있어요.","아래 도면에는 work-sleeping, living-dining, bath, sleeping, balcony, storage 가 적혀 있어요.","가장자리에 SOUTH WEST, SOUTH EAST, NORTH EAST 방위가 적혀 있어요.","방 이름이 두 개씩 붙어 있어요. 한 공간이 낮과 밤에 다르게 쓰인다는 뜻이에요.","오른쪽 두 사진은 같은 위층을 다른 각도에서 찍은 것이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.04,0.09,0.41,0.4],"c":[0.0195,0.07,0.451,0.44],"r":1.3667,"img":"img/U4/walk/p036_21_01.jpg","say":"왼쪽 위 청사진: studio, reading, hall 같은 방 이름이 보여요."},{"b":[0.04,0.53,0.41,0.38],"c":[0.0195,0.511,0.451,0.418],"r":1.4386,"img":"img/U4/walk/p036_21_02.jpg","say":"왼쪽 아래 청사진: work-sleeping, living-dining, balcony 가 보여요."},{"b":[0.5,0.045,0.47,0.46],"c":[0.4765,0.022,0.517,0.506],"r":1.3623,"img":"img/U4/walk/p036_21_03.jpg","say":"오른쪽 위 사진: 빨간 바닥 면 위에 빨강 파랑 의자가 놓여 있어요."},{"b":[0.5,0.53,0.47,0.46],"c":[0.4765,0.494,0.517,0.506],"r":1.3623,"img":"img/U4/walk/p036_21_04.jpg","say":"오른쪽 아래 사진: 창이 모서리까지 돌아가며 이어져요."}]}},{"p":37,"title":"슈뢰더 하우스 전경 사진 (글자 없는 슬라이드)","terms":["슈뢰더 하우스","Gerrit Rietveld"],"pass1":[{"kind":"say","lines":["이 슬라이드에는 글자가 하나도 없어요. 큰 사진 한 장뿐이에요.","앞 쪽에서 이어지는 **슈뢰더 하우스** 를 길 건너에서 찍은 사진이에요.","캡션이 없어서 슬라이드 자체는 이름도 연도도 말해 주지 않아요.","그래서 보이는 것만 짚어 볼게요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["흰 면과 회색 면이 서로 다른 높이로 어긋나게 붙어 있어요.","2층 모서리가 통유리로 되어 있고 창틀 안에 빨강, 파랑, 노랑 선이 들어가 있어요.","벽 한쪽에 빨간 세로 막대가 붙어 있어요. 구조가 아니라 색 요소예요.","왼쪽 흰 판은 벽에서 떨어져 나와 발코니 지붕이 돼요.","왼쪽 끝에 붙은 벽돌집과 비교하면 이 집만 판으로 지은 것처럼 보여요.","**헤리트 리트펠트(Gerrit Rietveld)** 의 판 구성이 실제로 어떻게 보이는지 확인하는 사진이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.015,0.94,0.97],"c":[0.0,0.0,1,1],"r":1.3333,"img":"img/U4/walk/p037_21_01.jpg","say":"사진 한 장이에요. 길 건너에서 집 전체를 찍었어요."},{"b":[0.3,0.2,0.4,0.3],"c":[0.28,0.184,0.44,0.332],"r":1.7671,"img":"img/U4/walk/p037_21_02.jpg","say":"2층 모서리 유리창. 창틀 안에 빨강, 파랑, 노랑 선이 있어요."},{"b":[0.44,0.55,0.16,0.2],"c":[0.42,0.534,0.2,0.232],"r":1.1494,"img":"img/U4/walk/p037_21_03.jpg","say":"벽에 붙은 빨간 세로 막대가 눈에 띄어요."},{"b":[0.13,0.2,0.14,0.45],"c":[0.1,0.1775,0.2,0.495],"r":0.5387,"img":"img/U4/walk/p037_21_04.jpg","say":"왼쪽 흰 판이 벽에서 떨어져 나와 발코니를 만들어요."}]}},{"p":38,"title":"슈뢰더 하우스 정면과 모서리 (글자 없는 슬라이드)","terms":["슈뢰더 하우스"],"pass1":[{"kind":"say","lines":["이 슬라이드에도 글자가 없어요. 사진 두 장만 있어요.","앞 쪽에 이어지는 **슈뢰더 하우스** 사진이에요.","왼쪽은 모서리를 가까이, 오른쪽은 정면 전체를 찍었어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 사진: 2층 유리 상자가 벽 앞으로 튀어나와 있어요.","그 유리 안쪽에 빨강, 파랑 선이 보여요. 아래에는 빨간 세로 막대가 있어요.","오른쪽 사진: 회색 면과 흰 면이 위아래로 어긋나 붙어 있어요.","1층 현관 앞에 흰 판이 앞으로 튀어나와 차양처럼 걸려 있어요.","지붕 위로 옛 벽돌집이 보여요. 두 집의 생김새가 완전히 달라요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.045,0.11,0.36,0.79],"c":[0.027,0.0705,0.396,0.869],"r":0.6076,"img":"img/U4/walk/p038_21_01.jpg","say":"왼쪽 사진: 모서리 유리창이 튀어나온 부분이에요."},{"b":[0.2,0.3,0.14,0.2],"c":[0.17,0.284,0.2,0.232],"r":1.1494,"img":"img/U4/walk/p038_21_02.jpg","say":"유리창 안쪽에 빨강, 파랑 선이 보여요."},{"b":[0.535,0.11,0.44,0.79],"c":[0.513,0.0705,0.484,0.869],"r":0.7426,"img":"img/U4/walk/p038_21_03.jpg","say":"오른쪽 사진: 집 정면이에요. 회색 면과 흰 면이 어긋나 있어요."},{"b":[0.58,0.45,0.12,0.25],"c":[0.54,0.434,0.2,0.282],"r":0.9456,"img":"img/U4/walk/p038_21_04.jpg","say":"흰 판이 앞으로 튀어나와 차양을 만들어요."}]}},{"p":39,"title":"슈뢰더 하우스 네 컷 (글자 없는 슬라이드)","terms":["슈뢰더 하우스","De Stijl"],"pass1":[{"kind":"say","lines":["글자 없이 사진 네 장만 있는 슬라이드예요.","앞 쪽에서 계속되는 **슈뢰더 하우스** 를 네 방향에서 찍었어요.","**데 스테일(De Stijl)** 의 색과 선이 실제로 어디에 쓰였는지 확인해요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 위: 2층 유리 상자를 가까이 본 사진이에요. 노란 선이 유리 가운데를 가로질러요.","오른쪽 위: 길 쪽에서 본 전경이에요. 노란 기둥이 벽 앞에 길게 서 있어요.","왼쪽 아래: 빨강, 노랑 선이 벽면과 창틀을 가로세로로 나눠요.","오른쪽 아래: 모서리 유리창을 아주 가까이 찍었어요. 빨강, 노랑 띠가 유리 위에 지나가요.","네 장 모두 색은 빨강, 파랑, 노랑과 흰색, 회색, 검정뿐이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["p.36부터 p.39까지는 글자 설명이나 캡션이 없는 사진 슬라이드예요.","이름과 연도는 p.33 캡션에서 가져와야 해요. **슈뢰더 하우스**, 위트레흐트, 1924년이에요."]}],"walk":{"head":null,"parts":[{"b":[0.01,0.015,0.47,0.48],"c":[0,0,0.517,0.528],"r":1.3056,"img":"img/U4/walk/p039_21_01.jpg","say":"왼쪽 위: 2층 유리 상자를 가까이 본 사진이에요."},{"b":[0.505,0.015,0.475,0.46],"c":[0.4775,0,0.5225,0.506],"r":1.3768,"img":"img/U4/walk/p039_21_02.jpg","say":"오른쪽 위: 길 쪽에서 본 전경이에요. 노란 기둥이 서 있어요."},{"b":[0.01,0.505,0.47,0.48],"c":[0,0.472,0.517,0.528],"r":1.3056,"img":"img/U4/walk/p039_21_03.jpg","say":"왼쪽 아래: 빨강, 노랑 선이 벽과 창을 나눠요."},{"b":[0.505,0.505,0.475,0.48],"c":[0.4775,0.472,0.5225,0.528],"r":1.3194,"img":"img/U4/walk/p039_21_04.jpg","say":"오른쪽 아래: 모서리 유리창을 아주 가까이 찍었어요."}]}},{"p":40,"title":"테오 반 두스뷔르흐, 카페 로베뜨(l'Aubette), 프랑스 스트라스부르, 1928","terms":["Theo Van Doesburg","l'Aubette","De Stijl","Bauhaus"],"pass1":[{"kind":"say","lines":["그림 두 장이에요. 왼쪽은 마름모 구성 그림, 오른쪽은 실내 투시도예요.","**테오 반 두스뷔르흐(Theo Van Doesburg)** 의 **카페 로베뜨(l'Aubette)** 예요.","프랑스 스트라스부르, 1928년이에요.","앞의 두 작품과 다른 점이 하나 있어요. 대각선이 들어와요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**카페 로베뜨(l'Aubette)**: 바와 무도회장, 시네마가 있는 복합 레스토랑의 실내 디자인이에요.","엔터테인먼트 센터: 먹고 마시고 춤추고 영화도 보는 복합 놀이 공간이에요."]},{"kind":"points","head":"이 그림에서 볼 것","items":["설계자, 작품, 도시, 연도는 **테오 반 두스뷔르흐(Theo Van Doesburg)**, **카페 로베뜨(l'Aubette)**, 프랑스 스트라스부르, 1928년이에요.","기하학적이며 추상적인 대각선으로 배치된 3차원적 형태들이 있어요.","튜브 모양의 계단과 발코니 난간이 그와 조화를 이뤄요.","유일한 색상으로 검정과 흰색과 원색들을 썼어요.","재료는 콘크리트, 강철, 알루미늄, 유리예요. 나무는 피했어요.","수평 수직의 요소 위에 대각선 요소를 조합하여 추상적인 벽면 디자인을 완성했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카페 로베뜨(l'Aubette)** 에서 반 두스뷔르흐가 수평 수직 요소 위에 조합한 것은 무엇일까요?","choices":["곡선 요소","대각선 요소","벽돌 요철"],"a":1,"why":"대각선 요소예요. 몬드리안의 직선 구성과 갈라지는 지점이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**데 스테일(De Stijl)** 하면 직선만 떠오르지만 **카페 로베뜨(l'Aubette)** 는 대각선을 써요.","독일의 **바우하우스(Bauhaus)** 가 직선 상자를 지을 때 네덜란드에서는 대각선까지 나아간 셈이에요."]},{"kind":"english","head":"논술 답안: 카페 로베뜨","en":"테오 반 두스뷔르흐의 카페 로베뜨(스트라스부르, 1928)는 바와 무도회장, 시네마가 있는 복합 레스토랑으로, 데 스테일의 기하학 형태를 사용하여 수평 수직의 요소 위에 대각선 요소를 조합한 추상적인 벽면 디자인을 완성하였다.","ko":"용도(복합 레스토랑), 형태(대각선 조합) 두 덩어리면 충분해요.","tip":"'로베뜨는 대각선' 한 마디로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.035,0.9,0.1],"c":[0.005,0,0.99,0.2],"r":6.6,"img":"img/U4/walk/p040_22_01.jpg","say":"제목 줄과 작품 이름이에요. 테오 반 두스뷔르흐(1883-1931), 카페 로베뜨."},{"b":[0.04,0.16,0.93,0.21],"c":[0,0.144,1,0.242],"r":5.5096,"img":"img/U4/walk/p040_22_02.jpg","say":"대각선 형태와 튜브 계단, 그리고 검정, 흰색, 원색으로 된 벽화 설명이에요."},{"b":[0.42,0.96,0.56,0.035],"c":[0.384,0.8755,0.616,0.1245],"r":6.5971,"img":"img/U4/walk/p040_22_03.jpg","say":"캡션: 테오 반 뒤스부르흐, 카페 로베뜨(l'Aubette), 프랑스 스트라스부르, 1928."},{"b":[0.04,0.38,0.93,0.13],"c":[0,0.3417,1,0.2067],"r":6.4506,"img":"img/U4/walk/p040_22_04.jpg","say":"바와 무도회장, 시네마가 있는 복합 레스토랑이라는 문장이에요."},{"b":[0.04,0.5,0.8,0.05],"c":[0,0.4361,0.88,0.1778],"r":6.5992,"img":"img/U4/walk/p040_22_05.jpg","say":"수평 수직 위에 대각선을 조합했다는 핵심 한 줄이에요."},{"b":[0.13,0.555,0.3,0.41],"c":[0.115,0.5345,0.33,0.451],"r":0.9756,"img":"img/U4/walk/p040_22_06.jpg","say":"왼쪽 그림: 마름모 안에 색 면들이 떠 있는 구성이에요."}]}},{"p":41,"title":"카페 로베뜨(l'Aubette), 2016년 복원","terms":["l'Aubette","Theo Van Doesburg","De Stijl","Art Nouveau"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 2016년에 복원한 **카페 로베뜨(l'Aubette)** 의 지금 모습이에요.","앞 쪽 흑백 투시도가 실제로 이렇게 색을 입고 있었어요.","천장과 벽에 큰 삼각형과 마름모가 대각선으로 깔려 있어요."]},{"kind":"recap","items":["4단원을 여기서 한 줄로 묶어요","**바우하우스(Bauhaus)** 는 기계로 잘 만드는 학교, **데 스테일(De Stijl)** 은 직선과 색으로 짓는 운동이에요.","2단원 **아르 누보(Art Nouveau)** 의 곡선에서 출발해 여기서 직선과 색 면만 남았어요.","주문을 마지막으로 한 번 더. 싫어 → 새 장식 → 정리 → 없애."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["캡션은 **테오 반 두스뷔르흐(Theo Van Doesburg)**, **카페 로베뜨(l'Aubette)**, 프랑스 스트라스부르, 2016년 복원이에요.","1928년이 원래 연도이고, 2016년은 복원한 해예요. 두 연도를 구분해요.","천장이 색 면으로 조각조각 나뉘어 있어요. 노랑, 파랑, 빨강, 검정이 보여요.","벽면에는 큰 삼각형과 마름모가 대각선으로 이어져요.","바닥도 색으로 나뉘어요. 나무 바닥, 빨간 면, 파란 면이 구역을 만들어요.","테이블과 칸막이도 흰 면과 검은 선으로 되어 있어 전체가 한 그림처럼 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**카페 로베뜨(l'Aubette)** 의 원래 완성 연도와 복원 연도는 각각 언제일까요?","choices":["1924년과 2002년","1928년과 2016년","1925년과 1979년"],"a":1,"why":"1928년에 완성하고 2016년에 복원했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**데 스테일(De Stijl)** 세 작품의 연도를 붙여 외워요.","**슈뢰더 하우스** 1924, **카페 더 우니** 1925, **카페 로베뜨(l'Aubette)** 1928이에요."]}],"walk":{"head":null,"parts":[{"b":[0.21,0.015,0.57,0.42],"c":[0.1815,0,0.627,0.462],"r":1.8095,"img":"img/U4/walk/p041_21_01.jpg","say":"위 사진: 천장과 벽에 색 면이 대각선으로 깔려 있어요."},{"b":[0.21,0.445,0.57,0.49],"c":[0.1815,0.4205,0.627,0.539],"r":1.551,"img":"img/U4/walk/p041_21_02.jpg","say":"아래 사진: 같은 방을 반대쪽에서 본 모습이에요. 바닥도 색으로 나뉘어요."},{"b":[0.2,0.955,0.62,0.04],"c":[0.169,0.8622,0.682,0.1378],"r":6.5989,"img":"img/U4/walk/p041_21_03.jpg","say":"캡션: 테오 반 뒤스부르흐, 카페 로베뜨(l'Aubette), 프랑스 스트라스부르, 2016년 복원."}]}}]};
